--
-- Name: gen_random_bytes(integer); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.gen_random_bytes(integer) RETURNS bytea
    LANGUAGE plpgsql
    AS $_$
DECLARE
    resultado bytea := ''::bytea;
    n int := GREATEST(1, LEAST($1, 8192));
    i int;
    b int;
BEGIN
    FOR i IN 1..n LOOP
        b := floor(random() * 256)::int;
        resultado := resultado || b::bytea;
    END LOOP;
    RETURN resultado;
END;
$_$;


