--

CREATE FUNCTION public.fn_agent_provisioning_origin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
 if tg_op='INSERT' then
  if current_user not in('postgres','service_role') then new.provisioning_origin:=null;end if;
 else
  new.provisioning_origin:=old.provisioning_origin;
  if(to_jsonb(new)-array['status','published_at','superseded_at','updated_at','provisioning_origin']) is distinct from(to_jsonb(old)-array['status','published_at','superseded_at','updated_at','provisioning_origin']) then new.provisioning_origin:=null;end if;
 end if;return new;
end;$$;


--
-- Name: fn_agent_tool_usage(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_agent_tool_usage(p_organization_id uuid, p_agent_id uuid, p_since timestamp with time zone) RETURNS TABLE(tool_name text, total bigint, falhas bigint, em_teste bigint, ultima_vez timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    a.metadata->>'tool_name'                                          as tool_name,
    count(*)::bigint                                                  as total,
    count(*) filter (where a.metadata->>'success' = 'false')::bigint   as falhas,
    count(*) filter (where r.is_dry_run)::bigint                       as em_teste,
    max(a.created_at)                                                 as ultima_vez
  from public.ai_agent_runs r
  join public.api_audit_log a
    on  a.request_id      = r.id::text
    and a.action          = 'mcp.tool_called'
    and a.organization_id = p_organization_id
    and a.created_at     >= p_since
  where r.organization_id = p_organization_id
    and r.agent_id        = p_agent_id
    and r.started_at     >= p_since
    and a.metadata->>'tool_name' is not null
  group by 1
$$;


