--

CREATE FUNCTION public.fn_carimbar_ida_ao_google() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- `now()` e n??o `new.updated_at`: os dois s??o o instante de in??cio da
  -- transa????o, ent??o o valor ?? o mesmo ??? e usar `now()` remove a depend??ncia de
  -- ORDEM entre este trigger e o de `updated_at`.
  if new.google_synced_at is not null
     and (tg_op = 'INSERT' or new.google_synced_at is distinct from old.google_synced_at) then
