COMMENT ON COLUMN public.followup_enrollments.timing_plan IS 'Plano de tempo das esperas adaptativas, decidido uma vez no acionamento do fluxo. null = sem plano (cai no max_ms de cada espera). Ver lib/followup/timing-plan.ts.';


--
-- Name: fn_claim_due_followup_enrollments(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_claim_due_followup_enrollments(p_limit integer, p_lease_seconds integer) RETURNS SETOF public.followup_enrollments
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with orgs as (
    -- Sem a condi????o de claim aqui de prop??sito: o lateral abaixo a aplica, e uma
    -- organiza????o cujos vencidos est??o todos com lease apenas devolve zero linhas.
    select distinct organization_id
      from followup_enrollments
     where status in ('active','waiting_reply','dormente')
       and next_eval_at <= now()
  ),
  fila as (
    select f.id, f.next_eval_at, f.posicao_na_org
      from orgs
      cross join lateral (
        select d.id,
               d.next_eval_at,
               row_number() over (order by d.next_eval_at) as posicao_na_org
          from followup_enrollments d
         where d.organization_id = orgs.organization_id
           and d.status in ('active','waiting_reply','dormente')
           and d.next_eval_at <= now()
           and (d.claimed_until is null or d.claimed_until < now())
         order by d.next_eval_at
         limit p_limit
      ) f
  ),
  escolhidos as (
    -- O rod??zio: posi????o 1 de todas as organiza????es, depois a 2 de todas, etc.
    -- Empate na mesma posi????o vai para quem esperou mais.
    select id from fila order by posicao_na_org, next_eval_at limit p_limit
  ),
  travados as (
    select e.id from followup_enrollments e
     where e.id in (select id from escolhidos)
     for update skip locked
  )
  update followup_enrollments e
     set claimed_until = now() + make_interval(secs => p_lease_seconds),
         updated_at = now()
   where e.id in (select id from travados)
     -- A condi????o de lease ?? REPETIDA AQUI, e n??o ?? redundante com a CTE `fila`.
     -- Sem ela, duas conex??es simult??neas reclamam as MESMAS linhas: a segunda
     -- espera o lock da primeira, e quando ele sai o Postgres (READ COMMITTED)
     -- reavalia s?? o WHERE do UPDATE ??? que n??o olhava `claimed_until` ??? e grava
     -- por cima. O `skip locked` da CTE n??o salva: as duas materializam a mesma
     -- lista antes de qualquer lock existir. Medido: interse????o de 5 em 5 no
     -- invariante de concorr??ncia (followup-schema.test.ts).
     and (e.claimed_until is null or e.claimed_until < now())
  returning e.*;
$$;


