--
-- Name: fn_conferir_modulos_instalados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_conferir_modulos_instalados() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_suspensos text;
begin
  select string_agg(modulo, ', ' order by modulo) into v_suspensos
    from public.modulos_instalados where estado = 'suspenso';
  -- A mensagem N??O repete o erro original, e isso ?? o ponto: se a provisionadora falhou com
  -- "already exists" e o texto viesse junto, a linha casaria com a lista de erros benignos do
  -- kit e seria ENGOLIDA ??? exatamente o sil??ncio que esta fun????o existe para impedir. O motivo
  -- fica em modulos_instalados.motivo_suspensao; o aviso s?? nomeia o m??dulo.
  if v_suspensos is not null then
    raise exception 'modulo suspenso na atualizacao: % ??? o motivo esta em modulos_instalados.motivo_suspensao', v_suspensos;
  end if;
end $$;


--
-- Name: fn_configurar_pre_go_live_canal(uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_configurar_pre_go_live_canal(p_org uuid, p_canal uuid, p_modo text, p_numeros text[]) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_linhas integer;
  v_gate text;
begin
  if p_modo is null or p_modo not in ('open', 'pre_go_live') then
    raise exception 'modo de acesso da IA inv??lido' using errcode = '22023';
  end if;

  if p_numeros is null or exists (
    select 1
      from unnest(p_numeros) as n(numero)
     where numero is null or numero !~ '^\+[1-9][0-9]{7,14}$'
  ) then
    raise exception 'lista de telefones de teste inv??lida' using errcode = '22023';
  end if;

  v_gate := case when p_modo = 'pre_go_live' then 'allowlist' else 'open' end;

  update public.channel_sessions
     set metadata = jsonb_set(
       jsonb_set(
         jsonb_set(coalesce(metadata, '{}'::jsonb), '{ai_gate}', to_jsonb(v_gate), true),
         -- O modo REAL, n??o o literal (o defeito da issue #602).
         '{ai_gate_mode}', to_jsonb(p_modo), true
       ),
       '{ai_test_phone_numbers}', to_jsonb(p_numeros), true
     )
   where organization_id = p_org
     and id = p_canal
     and archived_at is null;

  get diagnostics v_linhas = row_count;
  return v_linhas;
end;
$_$;


