--
-- Name: fn_conversation_assign(uuid, uuid, uuid, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_conversation_assign(p_organization_id uuid, p_conversation_id uuid, p_to_user_id uuid, p_reason text, p_expected_assignee uuid DEFAULT NULL::uuid, p_enforce_expected boolean DEFAULT false) RETURNS SETOF public.conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_from uuid;
  v_conv public.conversations%rowtype;
begin
  if not public.fn_support_write_allowed(p_organization_id) then raise exception 'support_readonly' using errcode='42501'; end if;
  if auth.uid() is not null
     and not public.fn_role_at_least(p_organization_id, 'agent') then
    raise exception 'caller_not_authorized_for_org'
      using hint = 'caller must be an active agent+ member of the organization';
  end if;

  if p_to_user_id is not null then
    if coalesce(public.fn_member_role_in_org(p_to_user_id, p_organization_id), 'none')
         not in ('agent','manager','admin') then
      raise exception 'assignee_not_eligible_member'
        using hint = 'target must be an active agent+ member of the organization';
    end if;
  end if;

  select assigned_to_user_id into v_from
    from public.conversations
   where id = p_conversation_id
     and organization_id = p_organization_id
   for no key update;

  if not found then
    return;
  end if;

  if p_enforce_expected and v_from is distinct from p_expected_assignee then
    return;
  end if;

  update public.conversations
     set assigned_to_user_id = p_to_user_id,
         -- Desnormalizado JUNTO com o dono, na mesma transa????o: nunca existe
         -- uma janela em que id e nome discordam. NULL junto com o id quando
         -- a atribui????o ?? removida (release) ??? nunca sobra um nome ??rf??o de
         -- dono nenhum. Lido de auth.users porque quem chama esta fun????o
         -- (RPC) n??o necessariamente tem acesso ao Admin API ??? a definer
         -- resolve por dentro.
         assigned_to_user_name = case
           when p_to_user_id is null then null
           else (select raw_user_meta_data ->> 'full_name' from auth.users where id = p_to_user_id)
         end,
         assigned_at = case when p_to_user_id is null then null else now() end,
         assignee_kind = case when p_to_user_id is null then null else 'user' end,
         status = case when p_to_user_id is null then 'open' else 'claimed' end,
         status_changed_at = now(),
         unread_count_for_assignee = 0,
         bot_silenced_until = case
           when p_reason = 'routing'  then bot_silenced_until
           when p_to_user_id is null  then (case when last_handoff_at is null
                                                 then null
                                                 else bot_silenced_until end)
           else 'infinity'::timestamptz
         end,
         updated_at = now()
   where id = p_conversation_id
   returning * into v_conv;

  insert into public.conversation_assignment_events
    (organization_id, conversation_id, from_user_id, to_user_id, changed_by, reason)
  values
    (p_organization_id, p_conversation_id, v_from, p_to_user_id, auth.uid(), p_reason);

  return next v_conv;
end;
$$;


--
-- Name: fn_corpos_de_lembrete_validos(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_corpos_de_lembrete_validos(p_corpos jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  select p_corpos is not null
     and jsonb_typeof(p_corpos) = 'object'
     and coalesce((select count(*) from jsonb_object_keys(p_corpos)), 0) <= 20
     and coalesce((
       select bool_and(
         e.key ~ '^[0-9]+$'
         and jsonb_typeof(e.value) = 'string'
         and length(e.value #>> '{}') <= 1000
       )
       from jsonb_each(p_corpos) as e
     ), true);
$_$;


--
-- Name: fn_create_tenant_with_owner(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_create_tenant_with_owner(p_actor uuid, p_key uuid, p_request jsonb, p_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  prior public.idempotency_keys%rowtype;
  org public.organizations%rowtype;
  result jsonb;
  dono_e_outra_pessoa boolean;
begin
  if not exists (select 1 from public.platform_admins where user_id = p_actor
    and revoked_at is null and scope = 'full') then
    raise exception 'platform_admin_required' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_actor::text || ':' || p_key::text, 0));
  select * into prior from public.idempotency_keys
    where key = p_key::text and endpoint = '/api/v1/admin/tenants:' || p_actor::text
      and expires_at > now() and tenant_creation_trusted;
  if found then
    if prior.request_hash <> decode(p_hash, 'hex') then
      raise exception 'idempotency_conflict' using errcode = '22023';
    end if;
    if prior.response_body->>'id' is distinct from prior.organization_id::text
      or not exists (select 1 from public.organizations where id = prior.organization_id and created_by = p_actor) then
      raise exception 'idempotency_provenance_invalid' using errcode = '22023';
    end if;
    return prior.response_body || jsonb_build_object('created', false);
  end if;

  -- A MESMA compara????o que j?? decidia `interface_settings`, agora com nome e
  -- guardada. Era ela que sabia a resposta e n??o a anotava em lugar nenhum.
  dono_e_outra_pessoa := lower(p_request->>'owner_email') is distinct from
    (select lower(email) from auth.users where id = p_actor);

  insert into public.organizations(display_name, slug, legal_name, cnpj, status, settings, created_by)
    values (p_request->>'display_name', p_request->>'slug', coalesce(nullif(p_request->>'legal_name', ''), p_request->>'display_name'),
      p_request->>'cnpj', 'active', jsonb_build_object('plan', p_request->>'plan'), p_actor)
    returning * into org;
  insert into public.user_organizations(organization_id, user_id, role, accepted_at, interface_settings, provisional_until_handover)
    values (org.id, p_actor, 'admin', now(),
      case when dono_e_outra_pessoa
        then '{"preset":"completa"}'::jsonb
        else coalesce(p_request->'owner_interface_settings', '{"preset":"completa"}'::jsonb) end,
      dono_e_outra_pessoa);
  result := jsonb_build_object('id', org.id, 'slug', org.slug, 'display_name', org.display_name,
    'invite_id', gen_random_uuid(), 'issued_at', floor(extract(epoch from now()))::bigint);
  insert into public.idempotency_keys(organization_id, key, endpoint, request_hash, status_code, response_body, tenant_creation_trusted)
    values (org.id, p_key::text, '/api/v1/admin/tenants:' || p_actor::text,
      decode(p_hash, 'hex'), 201, result, true);
  return result || jsonb_build_object('created', true);
end $$;


--
-- Name: fn_crm_lead_close_on_stage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_crm_lead_close_on_stage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_is_won  boolean;
  v_is_lost boolean;
begin
  if tg_op = 'UPDATE'
     and new.stage_id is not distinct from old.stage_id
     and new.status   is not distinct from old.status then
    return new;
  end if;

  select is_won, is_lost into v_is_won, v_is_lost
    from public.crm_stages where id = new.stage_id;

  if v_is_won then
    new.status := 'won';
    new.closed_at := coalesce(new.closed_at, now());
  elsif v_is_lost then
    new.status := 'lost';
    new.closed_at := coalesce(new.closed_at, now());
  else
    if tg_op = 'UPDATE' and old.status in ('won','lost') then
      new.status := 'open';
      new.closed_at := null;
    end if;
  end if;
  return new;
end$$;


--
-- Name: fn_decrypt_oauth(bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_decrypt_oauth(ciphertext bytea) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  k text := private.fn_oauth_key();
begin
  -- 1. Sem valor n??o h?? credencial (comportamento que a fun????o j?? tinha).
  if ciphertext is null then
    return null;
  end if;

  -- 2. Curto demais para ser pacote deste par: o menor que fn_encrypt_oauth
  --    produz (texto vazio, aes256) tem 66 bytes ??? medido. Abaixo disso ??
  --    sentinela (`\x00`, o byte de enfeite das rotas de sess??o), bytea vazio,
  --    lixo ou truncamento.
  if octet_length(ciphertext) < 66 then
    return null;
  end if;

  -- 3. Pacote PGP come??a com o bit 7 ligado (o real medido: 0xC3). Sem cara de
  --    pacote ?? JSON em claro, hex ou texto ??? e o tamanho sozinho n??o pega isso.
  --    Esta linha vem DEPOIS da de tamanho de prop??sito: `get_byte()` em bytea
  --    vazio estoura com `index 0 out of valid range, 0..-1` ??? medido.
  if get_byte(ciphertext, 0) < 128 then
    return null;
  end if;

  -- Daqui para baixo s?? chega pacote de verdade: se n??o abrir, ?? chave mestra
  -- trocada ou dado corrompido, e isso tem de aparecer.
  return pgp_sym_decrypt(ciphertext, k);
end$$;


--
-- Name: fn_definir_aviso_de_caso(uuid, uuid, text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_definir_aviso_de_caso(p_org uuid, p_channel uuid, p_telefone text, p_rotulo text, p_ligado boolean, p_confirma_contato boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_antes public.config_aviso_de_caso;
  v_arch timestamptz;
  v_digitos text;
  v_variantes text[];
begin
  -- Papel + suporte, nesta ordem e na MESMA transa????o da escrita. `auth.uid()`
  -- nulo ?? o caminho do service role: quem escreve configura????o ?? gente.
  if auth.uid() is null or p_org is null
     or not public.fn_role_at_least(p_org, 'admin')
     or not public.fn_support_write_allowed(p_org) then
    raise exception 'aviso_de_caso_forbidden' using errcode = '42501';
  end if;
  -- Quem N??O tem fator cadastrado passa: a fun????o j?? trata isso, e ?? coerente
  -- com a pol??tica de MFA opcional deste produto.
  if not public.fn_session_mfa_proven() then
    raise exception 'aviso_de_caso_mfa_required' using errcode = '42501';
  end if;
  if p_telefone is null or p_telefone !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'aviso_de_caso_telefone_invalido' using errcode = '22023';
  end if;

  -- O canal ?? DA organiza????o e n??o est?? arquivado. Sem isto a FK simples
  -- deixaria apontar para o canal de outro tenant ??? a FK composta do padr??o
  -- 0228 n??o serve aqui porque o `on delete set null` anularia tamb??m
  -- `organization_id`, que ?? a chave prim??ria desta tabela.
  if p_channel is not null then
    select archived_at into v_arch
      from public.channel_sessions
     where id = p_channel and organization_id = p_org;
    if not found or v_arch is not null then
      raise exception 'aviso_de_caso_canal_invalido' using errcode = '22023';
    end if;
  end if;

  -- As duas grafias do nono d??gito ??? a MESMA regra de
  -- `lib/channels/phone-variants.ts`. Comparar a string crua deixaria passar o
  -- n??mero do suporte cadastrado com 9 e registrado sem.
  v_digitos := regexp_replace(p_telefone, '\D', '', 'g');
  v_variantes := array[v_digitos];
  if v_digitos like '55%' then
    if length(v_digitos) = 13
       and substring(v_digitos from 5 for 1) = '9'
       and substring(v_digitos from 6 for 1) between '6' and '9' then
      v_variantes := v_variantes || (substring(v_digitos from 1 for 4) || substring(v_digitos from 6));
    elsif length(v_digitos) = 12
       and substring(v_digitos from 5 for 1) between '6' and '9' then
      v_variantes := v_variantes || (substring(v_digitos from 1 for 4) || '9' || substring(v_digitos from 5));
    end if;
  end if;

  -- O N??MERO DE AVISO N??O PODE SER UM N??MERO DA PR??PRIA ORGANIZA????O. ?? o la??o
  -- rob??-com-rob??: a conex??o de avisos manda para o n??mero oficial, o agente
  -- dele responde, e as duas pontas se alimentam sem fim.
  if exists (
       select 1 from public.channel_sessions s
        where s.organization_id = p_org
          and s.phone_number is not null
          and regexp_replace(s.phone_number, '\D', '', 'g') = any (v_variantes)) then
    raise exception 'aviso_de_caso_numero_da_propria_org' using errcode = '22023';
  end if;

  -- O n??mero de aviso vira INTERNO: tudo o que chegar dele deixa de virar
  -- contato, conversa, lead e despacho do agente. Se ele j?? ?? um CLIENTE desta
  -- organiza????o, as mensagens dessa pessoa param de chegar ao CRM ??? e isso n??o
  -- pode acontecer por engano. A tela pergunta e reenvia com `p_confirma_contato`.
  if not coalesce(p_confirma_contato, false) and exists (
       select 1 from public.contacts c
        where c.organization_id = p_org
          and c.phone_number is not null
          and regexp_replace(c.phone_number, '\D', '', 'g') = any (v_variantes)) then
    raise exception 'aviso_de_caso_numero_de_cliente' using errcode = '22023';
  end if;

  select * into v_antes from public.config_aviso_de_caso where organization_id = p_org;

  insert into public.config_aviso_de_caso
    (organization_id, channel_session_id, telefone_destino, rotulo, ligado, criado_por, atualizado_por)
  values
    (p_org, p_channel, p_telefone, nullif(btrim(p_rotulo), ''), coalesce(p_ligado, false), auth.uid(), auth.uid())
  on conflict (organization_id) do update
    set channel_session_id = excluded.channel_session_id,
        telefone_destino   = excluded.telefone_destino,
        rotulo             = excluded.rotulo,
        ligado             = excluded.ligado,
        atualizado_por     = auth.uid(),
        -- Trocou o n??mero, o JID resolvido do anterior n??o vale mais ??? e ?? o
        -- JID que o corte da ingest??o usa para reconhecer quem est?? em modo
        -- privacidade. Mant??-lo faria o corte continuar valendo para o n??mero
        -- ANTIGO, que pode voltar a ser um cliente.
        destino_jid        = case
                               when excluded.telefone_destino is distinct from config_aviso_de_caso.telefone_destino
                               then null
                               else config_aviso_de_caso.destino_jid
                             end,
        updated_at         = now();

  return jsonb_build_object(
    'trocou_numero', (v_antes.telefone_destino is distinct from p_telefone),
    'antes_ligado',  coalesce(v_antes.ligado, false)
  );
end;
$_$;


--
-- Name: fn_definir_cliente_pela_agenda(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_definir_cliente_pela_agenda(p_org uuid, p_ligado boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_settings jsonb;
  v_antes boolean;
  v_contato uuid;
  v_r text;
  v_ganharam integer := 0;
  v_perderam integer := 0;
begin
  if auth.uid() is null
     or p_org is null
     or p_ligado is null
     or not public.fn_role_at_least(p_org, 'admin')
     or not public.fn_support_write_allowed(p_org) then
    raise exception 'cliente_pela_agenda_forbidden' using errcode = '42501';
  end if;
  if not public.fn_session_mfa_proven() then
    raise exception 'cliente_pela_agenda_mfa_required' using errcode = '42501';
  end if;

  -- EXCLUSIVA, ANTES de ler qualquer coisa: espera todo INSERT/UPDATE de
  -- agendamento desta organiza????o que j?? passou pelo trigger (e segura a
  -- compartilhada at?? commitar), e faz os seguintes esperarem esta transa????o.
  -- Os comandos abaixo tiram snapshot novo e enxergam o que j?? commitou.
  perform pg_advisory_xact_lock(hashtextextended(p_org::text, 262));

  -- Sem `for update` na linha da organiza????o: a exclusiva acima j?? serializa
  -- esta fun????o consigo mesma e com o trigger, e a trava de linha barraria todo
  -- insert com FK para a organiza????o durante o la??o. O UPDATE abaixo toma s?? a
  -- trava que n??o conflita com essas FKs.
  select o.settings into v_settings
    from public.organizations o
   where o.id = p_org;
  if not found then
    raise exception 'organization_not_found' using errcode = 'P0002';
  end if;
  v_antes := (v_settings -> 'crm' -> 'cliente_pela_agenda') = 'true'::jsonb;

  -- Mescla dentro de `crm`: o que mais morar ali (hoje nada) n??o ?? apagado, e
  -- um `crm` que n??o seja objeto ?? substitu??do em vez de abortar.
  update public.organizations
     set settings = jsonb_set(
           coalesce(settings, '{}'::jsonb),
           '{crm}',
           (case when jsonb_typeof(settings -> 'crm') = 'object' then settings -> 'crm' else '{}'::jsonb end)
             || jsonb_build_object('cliente_pela_agenda', p_ligado),
           true)
   where id = p_org;

  -- O hist??rico, S?? na virada desligado ??? ligado, S?? desta organiza????o.
  if p_ligado and v_antes is not true then
    for v_contato in
      select c.id
        from public.contacts c
       where c.organization_id = p_org
         and c.is_anonymized = false
         and c.is_merged_into is null
         and (c.first_service_at is not null
              or exists (select 1 from public.calendar_appointments a
                          where a.organization_id = p_org and a.contact_id = c.id))
       order by c.id
    loop
      v_r := public.fn_recalcular_cliente_do_contato(p_org, v_contato, false);
      if v_r = 'etiquetado' then
        v_ganharam := v_ganharam + 1;
      elsif v_r = 'desetiquetado' then
        v_perderam := v_perderam + 1;
      end if;
    end loop;
  end if;

  -- O QUARTO N??MERO EXISTE PARA A TELA N??O MENTIR. Medido: numa organiza????o
  -- cujo ??nico contato TEM hor??rio marcado, todos cancelados, o corpo era
  -- `{ganharam: 0, perderam: 0, clientes: 0}` ??? e a ??ltima frase de
  -- `components/agenda/ClientePelaAgenda.tsx` dizia "Nenhum contato tinha
  -- hor??rio marcado ainda". Numa cl??nica com cancelamentos, que ?? o nicho que
  -- esta migration cita, essa ?? a primeira frase depois de ligar. Zero
  -- etiquetas novas tem QUATRO causas, e esta ?? a ??nica que os outros tr??s
  -- n??meros n??o distinguem.
  return jsonb_build_object(
    'ligado', p_ligado,
    'mudou', coalesce(v_antes, false) <> p_ligado,
    'ganharam_etiqueta', v_ganharam,
    'perderam_etiqueta', v_perderam,
    'clientes', (select count(*) from public.contacts
                  where organization_id = p_org and first_service_at is not null
                    and is_anonymized = false and is_merged_into is null),
    'com_agendamento_que_nao_conta', (
      select count(*) from public.contacts c
       where c.organization_id = p_org
         and c.first_service_at is null
         and c.is_anonymized = false and c.is_merged_into is null
         and exists (select 1 from public.calendar_appointments a
                      where a.organization_id = p_org and a.contact_id = c.id))
  );
end $$;


--
-- Name: fn_definir_colegas_podem_mexer_na_agenda(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_definir_colegas_podem_mexer_na_agenda(p_org uuid, p_ligado boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_atual boolean; v_linhas int;
begin
 if p_ligado is null then raise exception 'agenda_dos_colegas_invalido' using errcode='22023'; end if;
 if auth.uid() is null
    or not public.fn_role_at_least(p_org,'manager')
    or not public.fn_support_write_allowed(p_org) then
  raise exception 'agenda_dos_colegas_forbidden' using errcode='42501';
 end if;
 if not public.fn_session_mfa_proven() then raise exception 'mfa_required' using errcode='42501'; end if;
 v_atual := public.fn_colegas_podem_mexer_na_agenda(p_org);
 if v_atual is not distinct from p_ligado then
  return jsonb_build_object('ligado',v_atual,'mudou',false);
 end if;
 update public.organizations
    set settings = coalesce(settings,'{}'::jsonb) || jsonb_build_object('colegas_podem_mexer_na_agenda',to_jsonb(p_ligado))
  where id = p_org;
 get diagnostics v_linhas = row_count;
 if v_linhas = 0 then raise exception 'agenda_dos_colegas_sem_organizacao' using errcode='P0002'; end if;
 return jsonb_build_object('ligado',p_ligado,'mudou',true);
end; $$;


--
-- Name: FUNCTION fn_definir_colegas_podem_mexer_na_agenda(p_org uuid, p_ligado boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_definir_colegas_podem_mexer_na_agenda(p_org uuid, p_ligado boolean) IS 'Liga/desliga "Atendentes podem mexer na agenda dos colegas" (issue #978). Gerente ou acima, suporte de escrita e MFA comprovado; ela mesma confere pelo auth.uid(). Grava settings.colegas_podem_mexer_na_agenda e devolve {ligado,mudou}.';


--
-- Name: fn_definir_logo_da_organizacao(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_definir_logo_da_organizacao(p_org uuid, p_actor uuid, p_path text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_linhas integer;
  v_path   text;
begin
  if p_org is null or p_actor is null then
    raise exception 'logo_da_organizacao_argumento_nulo'
      using errcode = '22023';
  end if;

  v_path := nullif(btrim(coalesce(p_path, '')), '');

  -- O PREFIXO ASSEVERADO DENTRO DO BANCO ??? o gate que sobrevive ao segundo
  -- chamador. A rota monta o caminho a partir da organiza????o resolvida do
  -- cookie, mas "a rota monta certo" ?? promessa de UM chamador. Sem esta linha,
  -- um caminho de outro escopo (o `platform/...` que qualquer pessoa l?? no HTML
  -- da tela de login) entraria como logo da organiza????o ??? e o delete-on-replace
  -- da rota, rodando como `service_role`, apagaria o logo da instala????o inteira
  -- na troca seguinte.
  if v_path is not null
     and v_path !~ ('^' || p_org::text || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(png|jpg)$')
  then
    raise exception 'logo_da_organizacao_caminho_fora_do_escopo'
      using errcode = '22023';
  end if;

  if not exists (
       select 1 from public.user_organizations uo
        where uo.user_id = p_actor
          and uo.organization_id = p_org
          and uo.role = 'admin'
          and uo.revoked_at is null
     )
     and not exists (
       select 1 from public.platform_admins pa
        where pa.user_id = p_actor
          and pa.revoked_at is null
     )
  then
    raise exception 'logo_da_organizacao_sem_permissao'
      using errcode = '42501';
  end if;

  -- Merge no CAMPO. `jsonb_set` direto em '{branding,logo_path}' N??O serviria:
  -- com `branding` ausente, `create_missing` s?? cria a ??LTIMA chave e o caminho
  -- intermedi??rio faltando devolve o jsonb original intocado ??? silenciosamente.
  update public.organizations o
     set settings = case
           when v_path is null
             then jsonb_set(
                    coalesce(o.settings, '{}'::jsonb), '{branding}',
                    coalesce(o.settings -> 'branding', '{}'::jsonb) - 'logo_path', true)
           else jsonb_set(
                    coalesce(o.settings, '{}'::jsonb), '{branding}',
                    coalesce(o.settings -> 'branding', '{}'::jsonb)
                      || jsonb_build_object('logo_path', v_path), true)
         end
   where o.id = p_org;

  get diagnostics v_linhas = row_count;
  return v_linhas;
end;
$_$;


--
-- Name: FUNCTION fn_definir_logo_da_organizacao(p_org uuid, p_actor uuid, p_path text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_definir_logo_da_organizacao(p_org uuid, p_actor uuid, p_path text) IS 'Grava (ou apaga) organizations.settings.branding.logo_path com merge no CAMPO ??? n??o toca em app_name, accent_hex nem nas demais chaves de settings. Assevera que o caminho come??a pelo proprio organization_id: caminho de outro escopo levanta 22023. Papel insuficiente levanta 42501. Devolve linhas afetadas: 0 = a organiza????o n??o existe. Chamador: app/api/v1/marca/logo/route.ts.';


--
-- Name: fn_definir_marca_da_organizacao(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_definir_marca_da_organizacao(p_org uuid, p_actor uuid, p_marca jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_linhas integer;
  v_hex    text;
  v_limpar boolean;
begin
  if p_org is null or p_actor is null then
    raise exception 'marca_da_organizacao_argumento_nulo'
      using errcode = '22023';
  end if;

  v_limpar := p_marca is null or jsonb_typeof(p_marca) = 'null';

  if not v_limpar and jsonb_typeof(p_marca) <> 'object' then
    raise exception 'marca_da_organizacao_forma_invalida: %', jsonb_typeof(p_marca)
      using errcode = '22023';
  end if;

  v_hex := nullif(p_marca ->> 'accent_hex', '');
  if v_hex is not null and v_hex !~ '^#[0-9a-f]{6}$' then
    raise exception 'marca_da_organizacao_accent_hex_invalido'
      using errcode = '22023';
  end if;

  if not exists (
       select 1 from public.user_organizations uo
        where uo.user_id = p_actor
          and uo.organization_id = p_org
          and uo.role = 'admin'
          and uo.revoked_at is null
     )
     and not exists (
       select 1 from public.platform_admins pa
        where pa.user_id = p_actor
          and pa.revoked_at is null
     )
  then
    raise exception 'marca_da_organizacao_sem_permissao'
      using errcode = '42501';
  end if;

  update public.organizations o
     set settings = case
           -- "Limpar" com logo gravado N??O apaga o logo: o campo tem controle
           -- pr??prio na tela, e limpar nome+cor responde a OUTRA pergunta.
           when v_limpar and coalesce(o.settings #>> '{branding,logo_path}', '') = ''
             then coalesce(o.settings, '{}'::jsonb) - 'branding'
           when v_limpar
             then jsonb_set(
                    coalesce(o.settings, '{}'::jsonb), '{branding}',
                    jsonb_build_object('logo_path', o.settings #> '{branding,logo_path}'), true)
           -- `p_marca || preservado`: o lado DIREITO vence em `||`, ent??o o
           -- `logo_path` gravado sobrevive ?? substitui????o do objeto.
           -- `jsonb_strip_nulls` S?? no fragmento preservado ??? nunca em `p_marca`,
           -- cujo `app_name: null` ?? um valor com significado.
           else jsonb_set(
                    coalesce(o.settings, '{}'::jsonb), '{branding}',
                    p_marca || jsonb_strip_nulls(
                      jsonb_build_object('logo_path', o.settings #> '{branding,logo_path}')), true)
         end
   where o.id = p_org;

  get diagnostics v_linhas = row_count;
  return v_linhas;
end;
$_$;


