--
-- Name: demandas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.demandas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    contact_id uuid NOT NULL,
    lead_id uuid,
    agent_case_id uuid,
    aberta_em timestamp with time zone DEFAULT now() NOT NULL,
    origem text DEFAULT 'inbound'::text NOT NULL,
    assunto text,
    estado text DEFAULT 'aberta'::text NOT NULL,
    dono_kind text DEFAULT 'ia'::text NOT NULL,
    dono_user_id uuid,
    proximo_passo text,
    proximo_passo_em timestamp with time zone,
    prazo_em timestamp with time zone,
    desfecho text,
    fechada_em timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    encerrada_por uuid,
    CONSTRAINT demandas_desfecho_check CHECK ((desfecho = ANY (ARRAY['resolvida'::text, 'convertida'::text, 'nao_procede'::text, 'encerrada_pelo_cliente'::text, 'perdida'::text, 'expirada_sem_resposta'::text]))),
    CONSTRAINT demandas_desfecho_coerente CHECK (((desfecho IS NULL) = (fechada_em IS NULL))),
    CONSTRAINT demandas_dono_humano_tem_user CHECK (((dono_kind <> 'humano'::text) OR (dono_user_id IS NOT NULL))),
    CONSTRAINT demandas_dono_kind_check CHECK ((dono_kind = ANY (ARRAY['ia'::text, 'humano'::text]))),
    CONSTRAINT demandas_estado_check CHECK ((estado = ANY (ARRAY['aberta'::text, 'em_atendimento'::text, 'aguardando_cliente'::text, 'resolvida'::text, 'encerrada'::text]))),
    CONSTRAINT demandas_origem_check CHECK ((origem = ANY (ARRAY['inbound'::text, 'handoff'::text, 'followup'::text, 'manual'::text, 'derivada'::text])))
);


