--
-- Name: fn_demanda_encerrar(uuid, uuid, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_demanda_encerrar(p_org uuid, p_demanda uuid, p_expected bigint, p_desfecho text, p_actor uuid) RETURNS public.demandas
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d public.demandas; pre_contact uuid;
begin
 if p_desfecho not in ('resolvida','convertida','nao_procede','encerrada_pelo_cliente','perdida','expirada_sem_resposta') then
  raise exception 'invalid_desfecho' using errcode='22023'; end if;
 select * into d from public.demandas where id=p_demanda and organization_id=p_org;
 if not found then raise exception 'demanda_not_found' using errcode='P0002'; end if;
 pre_contact:=d.contact_id;
 perform public.fn_service_lock(p_org,d.contact_id);
 select * into d from public.demandas where id=p_demanda and organization_id=p_org for no key update;
 if d.contact_id is distinct from pre_contact then raise exception 'service_contact_changed' using errcode='40001'; end if;
 if d.revision<>p_expected or d.fechada_em is not null then raise exception 'demanda_stale' using errcode='40001'; end if;
 update public.demandas set revision=revision+1,desfecho=p_desfecho,fechada_em=clock_timestamp(),
  encerrada_por=p_actor,estado=case when p_desfecho in ('resolvida','convertida') then 'resolvida' else 'encerrada' end,
  proximo_passo=null,proximo_passo_em=null,updated_at=clock_timestamp()
  where id=p_demanda and organization_id=p_org returning * into d;
 insert into public.crm_lead_activities(organization_id,lead_id,contact_id,source_module,source_id,type,payload,performed_at,performed_by_user_id)
 select p_org,l.id,d.contact_id,'crm',d.id,'demand_closed',jsonb_build_object('demanda_id',d.id,'desfecho',p_desfecho),clock_timestamp(),p_actor
 from public.crm_leads l where l.organization_id=p_org and l.contact_id=d.contact_id;
 return d;
end; $$;


--
-- Name: fn_demanda_fecha_com_conversa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_demanda_fecha_com_conversa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status not in ('resolved', 'closed') or old.status = new.status then
    return new;
  end if;

  update public.demandas d
     set estado = 'resolvida',
         desfecho = 'resolvida',
         fechada_em = now(),
         updated_at = now()
   where d.organization_id = new.organization_id
     and d.fechada_em is null
     and exists (
       select 1 from public.demanda_conversas dc
        where dc.demanda_id = d.id and dc.conversation_id = new.id
     )
     -- S?? fecha se TODAS as conversas da demanda estiverem encerradas: uma
     -- demanda que atravessou dois canais n??o acabou porque um deles fechou.
     and not exists (
       select 1
         from public.demanda_conversas dc2
         join public.conversations c2 on c2.id = dc2.conversation_id
        where dc2.demanda_id = d.id
          and c2.id <> new.id
          and c2.status not in ('resolved', 'closed')
     );

  return new;
end;
$$;


--
-- Name: fn_demanda_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_demanda_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
 if new.revision=old.revision and (new.proximo_passo,new.proximo_passo_em,new.estado,new.desfecho,new.fechada_em)
  is distinct from (old.proximo_passo,old.proximo_passo_em,old.estado,old.desfecho,old.fechada_em) then
  new.revision:=old.revision+1;
 end if;
 return new;
end; $$;


--
-- Name: fn_emit_agent_case_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_emit_agent_case_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_contact_id uuid;
  v_tipo text;
begin
  v_tipo := case when tg_op = 'INSERT' then 'ai.case_opened' else 'ai.case_closed' end;

  -- O contato viaja no PAYLOAD porque ele sempre existe por schema
  -- (`agent_cases.conversation_id` ?? not null e `conversations.contact_id` ??
  -- not null) e porque poupa o consumidor de uma ida ao banco. O consumidor
  -- mant??m o fallback de buscar, para n??o confiar em conven????o.
  select c.contact_id into v_contact_id
    from public.conversations c
   where c.id = new.conversation_id;

  perform public.emit_event(
    v_tipo,
    'agent_case',
    new.id,
    jsonb_build_object(
      'case_id',         new.id,
      'conversation_id', new.conversation_id,
      'contact_id',      v_contact_id,
      'lead_id',         new.lead_id,
      'agent_id',        new.agent_id,
      'source',          new.source,
      'status',          new.status
    ),
    '{}'::jsonb,
    new.organization_id   -- SEMPRE de `new`, nunca de par??metro: ?? o filtro de tenant
  );
  return null;            -- AFTER trigger: o retorno ?? ignorado
end;
$$;


