COMMENT ON FUNCTION public.fn_estampar_atribuicao_de_anuncio(p_org uuid, p_contact uuid, p_platform text, p_metadata jsonb) IS 'Grava de qual an??ncio (Meta Ads / Google Ads / site) um contato veio ??? s?? na primeira vez. `source_metadata = source_metadata || p_metadata` faz merge, nunca sobrescreve o que fn_upsert_wa_contact j?? gravou (waha_lid, waha_chat_id, notify_name). A guarda `source_metadata->>''ad_platform'' is null` ?? o primeiro-toque: clicar em outro an??ncio meses depois, numa conversa j?? aberta, n??o reescreve de onde a pessoa veio originalmente ??? o UPDATE casa zero linhas, silenciosamente. `organization_id = p_org` (issue #1248): a organiza????o ?? obrigat??ria e o contato de OUTRA organiza????o casa zero linhas ??? escrita cross-tenant barrada no `where`, n??o no chamador. security definer + revoke de anon/authenticated: s?? o backend (admin client no ingest de canal) chama isto.';


--
-- Name: fn_estornar_comanda(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_estornar_comanda(p_org uuid, p_sale uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sale   public.sales%rowtype;
  v_orig   public.financial_entries%rowtype;
  v_novo   uuid;
begin
  if auth.uid() is null or not public.fn_role_at_least(p_org, 'manager') then
    raise exception 'estorno_forbidden' using errcode = '42501';
  end if;

  select * into v_sale from public.sales
   where id = p_sale and organization_id = p_org for update;
  if not found then raise exception 'comanda_nao_encontrada' using errcode = 'P0002'; end if;
  if v_sale.status <> 'finalized' then
    raise exception 'comanda_nao_finalizada' using errcode = '22023';
  end if;
  if v_sale.reversed_at is not null then
    return jsonb_build_object('sale_id', v_sale.id, 'ja_estornada', true);
  end if;

  update public.sales set reversed_at = now(), reverse_reason = p_motivo where id = p_sale;

  -- O contra-lan??amento de cada entrada da comanda. A original N??O ?? tocada:
  -- ela est?? paga e ?? imut??vel (o trigger acima recusaria).
  for v_orig in
    select * from public.financial_entries
     where sale_id = p_sale and organization_id = p_org and origin = 'sale'
  loop
    insert into public.financial_entries
      (organization_id, account_id, account_plan_id, sale_id, direction, amount_cents,
       currency, description, status, paid_at, origin, reverses_entry_id, created_by_user_id)
    values (
      p_org, v_orig.account_id, v_orig.account_plan_id, p_sale,
      case when v_orig.direction = 'in' then 'out' else 'in' end,
      v_orig.amount_cents, v_orig.currency,
      format('Estorno da comanda #%s', v_sale.number), 'paid', now(), 'reversal',
      v_orig.id, auth.uid()
    )
    returning id into v_novo;
  end loop;

  -- A comiss??o vira 'reversed' ??? n??o some, porque ela existiu e algu??m pode j??
  -- ter sido pago por ela.
  update public.commissions c
     set status = 'reversed', reversed_at = now()
    from public.sale_items i
   where c.sale_item_id = i.id and i.sale_id = p_sale and c.status <> 'reversed';

  -- E o ponto de fidelidade volta como movimento NEGATIVO, nunca apagando o
  -- ganho: o livro-raz??o conta as duas coisas.
  insert into public.loyalty_ledger
    (organization_id, contact_id, points, reason, sale_id, idempotency_key, created_by_user_id)
  select p_org, v_sale.contact_id, -l.points, 'Estorno da comanda', p_sale,
         format('reversal:%s', p_sale), auth.uid()
    from public.loyalty_ledger l
   where l.sale_id = p_sale and l.organization_id = p_org and l.points > 0
     and v_sale.contact_id is not null
  on conflict do nothing;

  return jsonb_build_object('sale_id', v_sale.id, 'estornada', true);
end $$;


--
-- Name: fn_event_log_e_registro(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_event_log_e_registro(p_event_type text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_event_type = any (array[
    -- IA e agente
    'ai.responded',
    'ai_agent.created',
    'ai_agent.published',
    'ai_agent.run_completed',
    'ai_agent.run_failed',
    'ai_agent.run_started',
    -- agente (harness) ??? o motor registra quando n??o h?? neg??cio para pendurar
    'agent.activity_unrouted',
    -- canal e conversa
    'channel_session.status_changed',
    'conversation.claimed',
    'conversation.transferred',
    'whatsapp.chat_id_not_recognized',
    'whatsapp.conversation_mark_failed',
    -- contato, lead, organiza????o e plataforma
    'contact.anonymized',
    'contact.created',
    'contact.deleted',
    'contact.updated',
    'crm.activity_write_failed',
    'incident.resolved',
    'lead.bulk_assigned',
    'lead.bulk_deleted',
    'lead.bulk_tagged',
    'lead.reopened',
    'lead.risk_backlog_seeded',
    'lead.updated',
    'org.updated',
    'tenant.onboarded',
    'tenant.reactivated',
    'tenant.suspended',
    'user.profile_updated',
    -- mensagem
    'message.failed',
    'message.outbound',
    'message.sending',
    'message.sent',
    -- LGPD
    'lgpd.export_delivered',
    'lgpd.export_generated',
    'lgpd.redact_applied',
    'lgpd.redact_failed'
  ]::text[]);
$$;


--
-- Name: fn_event_log_marca_registro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_event_log_marca_registro() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- S?? o que nasce `pending`: quem escolhe status na origem n??o ?? reescrito
  -- (o agent-engine insere `ai_agent.dispatch_requested` e
  -- `agent.operator_turn` com o status que quer).
  if new.status = 'pending' and public.fn_event_log_e_registro(new.event_type) then
    new.status := 'done';
  end if;
  return new;
end;
$$;


--
-- Name: fn_expurgar_auditoria_vencida(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_expurgar_auditoria_vencida(p_retencao_dias integer DEFAULT NULL::integer, p_limite integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  -- 1825 dias = os 5 anos da regra L-10; o piso de 90 impede que o knob vire
  -- apagador de rastro recente.
  v_dias int := greatest(coalesce(p_retencao_dias, 1825), 90);
  v_limite int := least(greatest(coalesce(p_limite, 1000), 1), 10000);
  v_apagadas int;
begin
  with vencidas as (
    select a.id
      from public.api_audit_log a
     where a.created_at < now() - make_interval(days => v_dias)
     order by a.created_at
     limit v_limite
  )
  delete from public.api_audit_log a
   using vencidas v
   where a.id = v.id;
  get diagnostics v_apagadas = row_count;
  return v_apagadas;
end;
$$;


--
-- Name: fn_expurgar_avisos_de_caso_vencidos(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_expurgar_avisos_de_caso_vencidos(p_retencao_dias integer DEFAULT NULL::integer, p_limite integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  -- 180 dias: mais curto que a auditoria (5 anos) porque a pergunta ??til ??? "o
  -- aviso daquele caso saiu?" ??? ?? de semanas, n??o de anos. O piso de 30 impede
  -- que o knob vire apagador do rastro de um incidente que ainda est?? sendo
  -- apurado, e mora AQUI, no corpo, porque s?? assim vale para QUALQUER
  -- chamador, inclusive um `psql` na m??o.
  v_dias int := greatest(coalesce(p_retencao_dias, 180), 30);
  v_limite int := least(greatest(coalesce(p_limite, 1000), 1), 10000);
  v_apagadas int;
begin
  with vencidas as (
    select e.id from public.entregas_de_aviso_de_caso e
     where e.created_at < now() - make_interval(days => v_dias)
     order by e.created_at
     limit v_limite
  )
  delete from public.entregas_de_aviso_de_caso e using vencidas v where e.id = v.id;
  get diagnostics v_apagadas = row_count;
  return v_apagadas;
end;
$$;


--
-- Name: fn_expurgar_conversa_do_caso_vencida(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_expurgar_conversa_do_caso_vencida(p_retencao_dias integer DEFAULT NULL::integer, p_limite integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  -- 365 = um ano fiscal: depois disso, "por que decidimos assim" ?? respondido
  -- pelos EVENTOS do caso, n??o pela delibera????o que os precedeu. O piso de 90
  -- impede que o knob vire apagador de rastro recente ??? o mesmo piso da
  -- auditoria, e pela mesma raz??o. O piso mora AQUI, no corpo, porque s?? assim
  -- ele vale para QUALQUER chamador, inclusive um `psql` na m??o.
  v_dias int := greatest(coalesce(p_retencao_dias, 365), 90);
  v_limite int := least(greatest(coalesce(p_limite, 1000), 1), 10000);
  v_apagadas int;
begin
  with vencidas as (
    select m.id from public.agent_case_chat_messages m
     where m.created_at < now() - make_interval(days => v_dias)
     order by m.created_at
     limit v_limite
  )
  delete from public.agent_case_chat_messages m using vencidas v where m.id = v.id;
  get diagnostics v_apagadas = row_count;
  return v_apagadas;
end;
$$;


--
-- Name: fn_expurgar_espelho_da_agenda(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_expurgar_espelho_da_agenda(p_retencao_dias integer DEFAULT NULL::integer, p_limite integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  -- 90 dias de passado vis??vel; piso de 7 porque isto ?? cache reconstru??vel pelo
  -- sync, e n??o rastro que precise sobreviver a um incidente.
  v_dias int := greatest(coalesce(p_retencao_dias, 90), 7);
  v_limite int := least(greatest(coalesce(p_limite, 1000), 1), 10000);
  v_apagadas int;
begin
  with vencidos as (
    select e.id
      from public.calendar_external_events e
     -- `ends_at` e n??o `created_at`: um compromisso futuro n??o envelhece, e
     -- apag??-lo faria a agenda marcar em cima de hora ocupada.
     where e.ends_at < now() - make_interval(days => v_dias)
     order by e.ends_at
     limit v_limite
  )
  delete from public.calendar_external_events e
   using vencidos v
   where e.id = v.id;
  get diagnostics v_apagadas = row_count;
  return v_apagadas;
end;
$$;


--
-- Name: fn_expurgar_nonces_de_oauth(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_expurgar_nonces_de_oauth(p_retencao_dias integer DEFAULT NULL::integer, p_limite integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_removidas int;
begin
  -- Piso no CORPO, como as irm??s: um chamador que passe 0 n??o apaga nonce que
  -- ainda protege. O prazo do state ?? de 10 minutos, ent??o um dia j?? ?? folga
  -- de duas ordens de grandeza.
  if p_retencao_dias is null or p_retencao_dias < 1 then
    p_retencao_dias := 1;
  end if;

  with alvo as (
    select nonce
      from public.calendar_oauth_nonces
     where expira_em < now() - make_interval(days => p_retencao_dias)
     -- 500 era o default DECLARADO na 0190; agora mora no corpo, como nas
     -- irm??s, e o efeito de quem omite o argumento ?? o mesmo.
     limit greatest(coalesce(p_limite, 500), 1)
  )
  delete from public.calendar_oauth_nonces n
   using alvo
   where n.nonce = alvo.nonce;

  get diagnostics v_removidas = row_count;
  return v_removidas;
end$$;


--
-- Name: fn_expurgar_passagens_vencidas(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_expurgar_passagens_vencidas(p_retencao_dias integer DEFAULT NULL::integer, p_limite integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  -- 1825 = os 5 anos da auditoria, e pelo mesmo motivo: a passagem ?? rastro de
  -- ATENDIMENTO ??? quem assumiu, quando, e por qu??. O piso de 90 impede que o
  -- knob vire apagador de rastro recente, e mora AQUI, no corpo, porque s?? assim
  -- vale para QUALQUER chamador, inclusive um `psql` na m??o.
  v_dias int := greatest(coalesce(p_retencao_dias, 1825), 90);
  v_limite int := least(greatest(coalesce(p_limite, 1000), 1), 10000);
  v_apagadas int;
begin
  with vencidas as (
    select p.id from public.passagens_de_atendimento p
      -- ?????? S?? passagem J?? RECONHECIDA. Uma passagem aberta ?? demanda viva: algu??m
      -- do outro lado est?? esperando resposta e ningu??m assumiu. Apag??-la por
      -- idade seria o expurgo virando esquecedor de pend??ncia ??? e o ??nico sinal
      -- de que a pessoa ficou sem resposta some junto.
     where p.reconhecido_em is not null
       and p.criado_em < now() - make_interval(days => v_dias)
     order by p.criado_em
     limit v_limite
  )
  delete from public.passagens_de_atendimento p using vencidas v where p.id = v.id;
  get diagnostics v_apagadas = row_count;
  return v_apagadas;
end;
$$;


--
-- Name: fn_extensions_admit_catalog(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_admit_catalog(p_actor uuid, p_operation uuid, p_snapshot jsonb, p_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_request jsonb := jsonb_build_object('kind','catalog_admission','actor',p_actor,'snapshot',p_snapshot,'digest',p_digest);
  v_op public.extension_operations; v_catalog public.extension_catalogs; v_entry jsonb; v_revision integer;
begin
  perform public.fn_extensions_assert_actor(p_actor);
  if p_operation is null then raise exception using errcode='P0001', message='extension_invalid_input'; end if;
  perform pg_advisory_xact_lock(255,1);
  perform public.fn_extensions_assert_actor(p_actor);
  perform pg_advisory_xact_lock(hashtextextended(p_operation::text,255));
  perform public.fn_extensions_assert_actor(p_actor);
  select * into v_op from public.extension_operations where id=p_operation;
  if found then
    if v_op.request_fingerprint <> public.fn_extensions_fingerprint(v_request) then
      raise exception using errcode='P0001', message='extension_idempotency_conflict';
    end if;
    return to_jsonb(v_op) || jsonb_build_object('applied_now', false);
  end if;
  if p_snapshot is null or jsonb_typeof(p_snapshot) <> 'object'
    or not (p_snapshot ?& array['format_version','origin','revision','entries'])
    or p_snapshot - array['format_version','origin','revision','entries'] <> '{}'::jsonb
    or p_snapshot->'format_version' is distinct from '1'::jsonb
    or jsonb_typeof(p_snapshot->'origin') is distinct from 'string'
    or p_snapshot->>'origin' !~ '^https?://[^/@?#[:space:]]+$'
    or jsonb_typeof(p_snapshot->'revision') is distinct from 'number'
    or p_snapshot->>'revision' !~ '^[1-9][0-9]{0,8}$'
    or jsonb_typeof(p_snapshot->'entries') is distinct from 'array'
    or p_digest is null or p_digest !~ '^[a-f0-9]{64}$' then
    raise exception using errcode='P0001', message='extension_invalid_input';
  end if;
  if jsonb_array_length(p_snapshot->'entries') > 128 then
    raise exception using errcode='P0001', message='extension_invalid_input';
  end if;
  for v_entry in select value from jsonb_array_elements(p_snapshot->'entries') loop
    if jsonb_typeof(v_entry) <> 'object' or not (v_entry ?& array['publisher','name','version','license','host_api','display','permissions','sha256','byte_length'])
      or v_entry - array['publisher','name','version','license','host_api','display','permissions','sha256','byte_length','publisher_label','homepage','repository','tags','published_at'] <> '{}'::jsonb
      or exists (select 1 from jsonb_each(v_entry) e where e.value='null'::jsonb)
      or jsonb_typeof(v_entry->'byte_length') is distinct from 'number'
      or jsonb_typeof(v_entry->'host_api') is distinct from 'object'
      or jsonb_typeof(v_entry->'display') is distinct from 'object'
      or v_entry->>'publisher' !~ '^[a-z0-9][a-z0-9-]{0,62}[a-z0-9]$'
      or v_entry->>'name' !~ '^[a-z0-9][a-z0-9-]{0,62}[a-z0-9]$'
      or v_entry->>'version' !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
      or v_entry->>'sha256' !~ '^[a-f0-9]{64}$'
      or v_entry->>'byte_length' !~ '^[1-9][0-9]{0,4}$'
      or v_entry->>'license' <> 'MIT' or not public.fn_extensions_permissoes_validas(v_entry->'permissions') then
      raise exception using errcode='P0001', message='extension_invalid_input';
    end if;
    if (v_entry->>'byte_length')::integer > 65536 then
      raise exception using errcode='P0001', message='extension_invalid_input';
    end if;
  end loop;
  if exists (select 1 from jsonb_array_elements(p_snapshot->'entries') e
    group by e->>'publisher', e->>'name', e->>'version' having count(*) > 1) then
    raise exception using errcode='P0001', message='extension_invalid_input';
  end if;
  v_revision := (p_snapshot->>'revision')::integer;
  select * into v_catalog from public.extension_catalogs where origin=p_snapshot->>'origin';
  if found and (v_revision < v_catalog.revision or (v_revision = v_catalog.revision
      and (p_digest <> v_catalog.digest or p_snapshot <> v_catalog.snapshot))) then
    raise exception using errcode='P0001', message='extension_catalog_revision_conflict';
  end if;
  if v_catalog.id is null then
    if (select count(*) from public.extension_catalogs) >= 8 then
      raise exception using errcode='P0001',message='extension_catalog_limit';
    end if;
    insert into public.extension_catalogs(origin,revision,digest,snapshot,admitted_by)
      values(p_snapshot->>'origin',v_revision,p_digest,p_snapshot,p_actor) returning * into v_catalog;
  elsif v_revision > v_catalog.revision then
    update public.extension_catalogs set revision=v_revision,digest=p_digest,snapshot=p_snapshot,
      admitted_by=p_actor,admitted_at=now() where id=v_catalog.id returning * into v_catalog;
    update public.extension_operations set status='cancelled',error_code='extension_catalog_stale',updated_at=now()
      where catalog_id=v_catalog.id and kind in ('install','update') and status='preparing';
  end if;
  insert into public.extension_operations(id,kind,status,actor_id,catalog_id,request,request_fingerprint,result)
    values(p_operation,'catalog_admission','completed',p_actor,v_catalog.id,v_request,
      public.fn_extensions_fingerprint(v_request),jsonb_build_object('catalog',to_jsonb(v_catalog))) returning * into v_op;
  return to_jsonb(v_op) || jsonb_build_object('applied_now', true);
end $_$;


--
-- Name: fn_extensions_assert_actor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_assert_actor(p_actor uuid, p_organization uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_actor is null or not exists (select 1 from auth.users where id = p_actor) then
    raise exception using errcode = 'P0001', message = 'extension_forbidden';
  end if;
  if p_organization is null then
    if not exists (select 1 from public.platform_admins where user_id = p_actor and revoked_at is null and scope = 'full') then
      raise exception using errcode = 'P0001', message = 'extension_forbidden';
    end if;
  elsif not exists (select 1 from public.user_organizations where user_id = p_actor and organization_id = p_organization
    and revoked_at is null and accepted_at is not null and role = 'admin') then
    raise exception using errcode = 'P0001', message = 'extension_forbidden';
  end if;
end $$;


--
-- Name: fn_extensions_cancel_install(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_cancel_install(p_actor uuid, p_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_op public.extension_operations; v_applied boolean := false;
begin
  perform public.fn_extensions_assert_actor(p_actor);
  perform pg_advisory_xact_lock(255,1);
  perform public.fn_extensions_assert_actor(p_actor);
  select * into v_op from public.extension_operations where id=p_operation for update;
  if not found then raise exception using errcode='P0001',message='extension_operation_not_found'; end if;
  if v_op.kind not in ('install','update') then raise exception using errcode='P0001',message='extension_operation_conflict'; end if;
  -- Outro administrador atual pode recuperar uma prepara????o cujo ator foi removido.
  if v_op.status='preparing' then
    update public.extension_operations set status='cancelled',updated_at=now() where id=p_operation returning * into v_op;
    v_applied := true;
  end if;
  return to_jsonb(v_op) || jsonb_build_object('applied_now', v_applied);
end $$;


--
-- Name: fn_extensions_configure(uuid, uuid, uuid, uuid, integer, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_configure(p_actor uuid, p_organization uuid, p_installation uuid, p_operation uuid, p_expected_revision integer, p_enabled boolean, p_configuration jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request jsonb := jsonb_build_object('kind','configure','actor',p_actor,'organization',p_organization,
    'installation',p_installation,'expected_revision',p_expected_revision,'enabled',p_enabled,'configuration',p_configuration);
  v_op public.extension_operations; v_link public.organization_extensions; v_config jsonb; v_manifest jsonb;
  v_removed_at timestamptz;
begin
  if p_organization is null or p_operation is null or p_installation is null or p_expected_revision is null
    or p_expected_revision < 0 or p_enabled is null then
    raise exception using errcode='P0001',message='extension_invalid_input';
  end if;
  perform public.fn_extensions_assert_actor(p_actor,p_organization);
  perform pg_advisory_xact_lock(hashtextextended(p_operation::text,255));
  perform public.fn_extensions_assert_actor(p_actor,p_organization);
  select * into v_op from public.extension_operations where id=p_operation;
  if found then
    if v_op.request_fingerprint <> public.fn_extensions_fingerprint(v_request) then
      raise exception using errcode='P0001',message='extension_idempotency_conflict';
    end if;
    return to_jsonb(v_op) || jsonb_build_object('applied_now', false);
  end if;
  perform 1 from public.organizations where id=p_organization for update;
  perform public.fn_extensions_assert_actor(p_actor,p_organization);
  -- FOR SHARE na instala????o serializa a ativa????o com toda troca de ponteiro e com a remo????o
  -- (que faz UPDATE na instala????o antes dos v??nculos). Sem isso, configurar e remover ao mesmo
  -- tempo deixava um v??nculo ativo numa extens??o removida, que nenhuma tela desativava.
  select i.removed_at, a.manifest into v_removed_at, v_manifest
    from public.extension_installations i join public.extension_artifacts a on a.id=i.artifact_id
    where i.id=p_installation for share of i;
  if not found then raise exception using errcode='P0001',message='extension_installation_not_found'; end if;
  if v_removed_at is not null then raise exception using errcode='P0001',message='extension_removed'; end if;
  select * into v_link from public.organization_extensions where organization_id=p_organization and installation_id=p_installation;
  if coalesce(v_link.revision,0) <> p_expected_revision then
    raise exception using errcode='P0001',message='extension_revision_conflict';
  end if;
  v_config := coalesce(p_configuration,v_link.configuration,v_manifest->'configuration');
  if v_config is null or jsonb_typeof(v_config) <> 'object'
    or not (v_config ?& array['density','show_description']) or v_config - array['density','show_description'] <> '{}'::jsonb
    or v_config->>'density' is null or v_config->>'density' not in ('comfortable','compact')
    or jsonb_typeof(v_config->'show_description') is distinct from 'boolean' then
    raise exception using errcode='P0001',message='extension_invalid_input';
  end if;
  if p_enabled and not coalesce(v_link.enabled,false) and
    (select count(*) from public.organization_extensions where organization_id=p_organization and enabled) >= 8 then
    raise exception using errcode='P0001',message='extension_active_limit';
  end if;
  insert into public.organization_extensions(organization_id,installation_id,enabled,configuration,revision,updated_by)
    values(p_organization,p_installation,p_enabled,v_config,p_expected_revision+1,p_actor)
    on conflict (organization_id,installation_id) do update set enabled=excluded.enabled,configuration=excluded.configuration,
      revision=excluded.revision,updated_by=excluded.updated_by,updated_at=now(),
      -- Ativar apaga a marca da remo????o; desativar ou mudar a densidade a preserva.
      deactivated_by_removal_at=case when excluded.enabled then null else organization_extensions.deactivated_by_removal_at end
    returning * into v_link;
  insert into public.extension_operations(id,kind,status,actor_id,organization_id,installation_id,request,request_fingerprint,result)
    values(p_operation,'configure','completed',p_actor,p_organization,p_installation,v_request,
      public.fn_extensions_fingerprint(v_request),jsonb_build_object('organization_extension',to_jsonb(v_link))) returning * into v_op;
  return to_jsonb(v_op) || jsonb_build_object('applied_now', true);
end $$;


--
-- Name: fn_extensions_core_update_in_progress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_core_update_in_progress() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from public.system_update_runs
    where status='dispatched' and dispatched_at > now() - interval '15 minutes');
$$;


--
-- Name: fn_extensions_fail_install(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_fail_install(p_actor uuid, p_operation uuid, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_op public.extension_operations; v_applied boolean := false;
begin
  perform public.fn_extensions_assert_actor(p_actor);
  if p_error_code is null or p_error_code not in ('extension_invalid_package','extension_incompatible','extension_download_failed',
      'extension_unsafe_origin','extension_digest_mismatch','extension_payload_too_large','extension_storage_failed') then
    raise exception using errcode='P0001',message='extension_invalid_input';
  end if;
  perform pg_advisory_xact_lock(255,1);
  perform public.fn_extensions_assert_actor(p_actor);
  select * into v_op from public.extension_operations where id=p_operation for update;
  if not found then raise exception using errcode='P0001',message='extension_operation_not_found'; end if;
  if v_op.kind not in ('install','update') or v_op.actor_id is distinct from p_actor then
    raise exception using errcode='P0001',message='extension_operation_conflict';
  end if;
  if v_op.status='preparing' then
    update public.extension_operations set status='failed',error_code=p_error_code,updated_at=now()
      where id=p_operation returning * into v_op;
    v_applied := true;
  elsif v_op.status='failed' and v_op.error_code is distinct from p_error_code then
    raise exception using errcode='P0001',message='extension_idempotency_conflict';
  end if;
  return to_jsonb(v_op) || jsonb_build_object('applied_now', v_applied);
end $$;


--
-- Name: fn_extensions_fingerprint(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_fingerprint(p_request jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  select encode(digest(convert_to(p_request::text, 'UTF8'), 'sha256'), 'hex');
$$;


--
-- Name: fn_extensions_finish_install(uuid, uuid, jsonb, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_finish_install(p_actor uuid, p_operation uuid, p_manifest jsonb, p_sha256 text, p_byte_length integer, p_document text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_op public.extension_operations; v_catalog public.extension_catalogs;
  v_artifact public.extension_artifacts; v_install public.extension_installations; v_current public.extension_artifacts;
  v_previous public.extension_artifacts; v_document_json jsonb; v_active integer := 0;
begin
  perform public.fn_extensions_assert_actor(p_actor);
  perform pg_advisory_xact_lock(255,1);
  perform public.fn_extensions_assert_actor(p_actor);
  select * into v_op from public.extension_operations where id=p_operation for update;
  if not found then raise exception using errcode='P0001',message='extension_operation_not_found'; end if;
  if v_op.kind not in ('install','update') or v_op.actor_id is distinct from p_actor then
    raise exception using errcode='P0001',message='extension_operation_conflict';
  end if;
  -- Sem autoridade ap??s cancel/fail. Resposta perdida de completed segue verificando payload.
  if v_op.status in ('cancelled','failed') then return to_jsonb(v_op) || jsonb_build_object('applied_now', false); end if;
  if p_document is null or octet_length(p_document) not between 1 and 65536
    or octet_length(p_document) is distinct from p_byte_length
    or encode(sha256(convert_to(p_document,'UTF8')),'hex') is distinct from p_sha256 then
    raise exception using errcode='P0001',message='extension_artifact_mismatch';
  end if;
  begin
    v_document_json := p_document::jsonb;
  exception when invalid_text_representation or untranslatable_character or program_limit_exceeded then
    raise exception using errcode='P0001',message='extension_artifact_mismatch';
  end;
  if v_document_json is distinct from p_manifest then
    raise exception using errcode='P0001',message='extension_artifact_mismatch';
  end if;
  if p_sha256 is distinct from v_op.entry->>'sha256' or p_byte_length is distinct from (v_op.entry->>'byte_length')::integer
    or p_manifest is null or jsonb_typeof(p_manifest) <> 'object'
    or not (p_manifest ?& array['format_version','profile','publisher','name','version','license','host_api','permissions','dependencies','data','display','configuration','contributions'])
    or p_manifest - array['format_version','profile','publisher','name','version','license','host_api','permissions','dependencies','data','display','configuration','contributions'] <> '{}'::jsonb
    or exists (select 1 from jsonb_each(p_manifest) e where e.value='null'::jsonb)
    or p_manifest->'format_version' is distinct from '1'::jsonb or p_manifest->>'profile' is distinct from 'declarative'
    or jsonb_typeof(p_manifest->'configuration') is distinct from 'object'
    or jsonb_typeof(p_manifest->'contributions') is distinct from 'object'
    or p_manifest->>'publisher' is distinct from v_op.publisher or p_manifest->>'name' is distinct from v_op.name
    or p_manifest->>'version' is distinct from v_op.version
    or p_manifest->'dependencies' <> '[]'::jsonb or p_manifest->'data' <> '{"mode":"none"}'::jsonb
    or (p_manifest - array['format_version','profile','dependencies','data','configuration','contributions'])
      is distinct from (v_op.entry - array['sha256','byte_length']) then
    raise exception using errcode='P0001',message='extension_artifact_mismatch';
  end if;
  if v_op.status='completed' then
    -- Compara com o artefato que ESTA conclus??o publicou, n??o com o ponteiro de agora: um
    -- "desfazer" posterior n??o pode fazer a repeti????o acusar pacote adulterado.
    select * into v_artifact from public.extension_artifacts
      where id=coalesce(v_op.result->>'to_artifact_id', v_op.result->'installation'->>'artifact_id')::uuid;
    if not found or v_artifact.manifest is distinct from p_manifest or v_artifact.document is distinct from p_document then
      raise exception using errcode='P0001',message='extension_artifact_mismatch';
    end if;
    return to_jsonb(v_op) || jsonb_build_object('applied_now', false);
  end if;
  if public.fn_extensions_core_update_in_progress() then
    raise exception using errcode='P0001',message='extension_core_update_in_progress';
  end if;
  select * into v_catalog from public.extension_catalogs where id=v_op.catalog_id;
  if v_catalog.revision is distinct from v_op.admission_revision or v_catalog.digest is distinct from v_op.admission_digest then
    raise exception using errcode='P0001',message='extension_catalog_stale';
  end if;
  select * into v_install from public.extension_installations
    where catalog_id=v_op.catalog_id and publisher=v_op.publisher and name=v_op.name for update;
  -- Defesa estrutural: a linha tem de estar na revis??o que a prepara????o viu.
  if v_install.revision is distinct from (v_op.result->>'from_revision')::integer
    or (v_op.kind='update' and v_install.removed_at is not null)
    or (v_op.kind='install' and v_install.id is not null and v_install.removed_at is null) then
    raise exception using errcode='P0001',message='extension_version_changed';
  end if;
  if v_install.id is not null then
    select * into v_current from public.extension_artifacts where id=v_install.artifact_id;
    -- A recusa que a spec v1 prometeu para "quando o contrato admitir outra permiss??o".
    -- Sem ela, 1.0 -> 1.1 acrescentaria uma porta sem ningu??m na organiza????o rever a lista
    -- que a tela existe para mostrar: o furo entra pela porta lateral da pr??pria propriedade
    -- que a lista de permiss??es garante. Mudar o conjunto de portas ?? outra extens??o.
    if v_op.kind='update' and v_current.id is not null
      and v_current.manifest->'permissions' is distinct from p_manifest->'permissions' then
      raise exception using errcode='P0001',message='extension_permissions_changed';
    end if;
    select * into v_previous from public.extension_artifacts where id=v_install.previous_artifact_id;
    if (v_install.version = v_op.version and v_current.sha256 <> p_sha256)
      or (v_previous.id is not null and v_previous.manifest->>'version' = v_op.version and v_previous.sha256 <> p_sha256) then
      raise exception using errcode='P0001',message='extension_version_conflict';
    end if;
  end if;
  select * into v_artifact from public.extension_artifacts where sha256=p_sha256;
  if found then
    if v_artifact.manifest is distinct from p_manifest or v_artifact.document is distinct from p_document or v_artifact.byte_length <> p_byte_length then
      raise exception using errcode='P0001',message='extension_artifact_mismatch';
    end if;
  else
    insert into public.extension_artifacts(sha256,byte_length,manifest,document) values(p_sha256,p_byte_length,p_manifest,p_document) returning * into v_artifact;
  end if;
  if v_install.id is null then
    insert into public.extension_installations(catalog_id,artifact_id,publisher,name,version,installed_by)
      values(v_op.catalog_id,v_artifact.id,v_op.publisher,v_op.name,v_op.version,p_actor) returning * into v_install;
  elsif v_op.kind='install' then
    -- Reinstala????o de uma linha removida: os v??nculos N??O voltam ativos; cada organiza????o decide.
    update public.extension_installations set artifact_id=v_artifact.id, version=v_op.version, previous_artifact_id=null,
      removed_at=null, removed_by=null, installed_by=p_actor, installed_at=now(), revision=revision+1
      where id=v_install.id returning * into v_install;
  else
    update public.extension_installations set previous_artifact_id=artifact_id, artifact_id=v_artifact.id,
      version=v_op.version, revision=revision+1 where id=v_install.id returning * into v_install;
    select count(*)::integer into v_active from public.organization_extensions where installation_id=v_install.id and enabled;
  end if;
  update public.extension_operations set status='completed',installation_id=v_install.id,
    result=coalesce(v_op.result,'{}'::jsonb) || jsonb_build_object('installation',to_jsonb(v_install),
      'to_artifact_id',v_artifact.id,'to_version',v_op.version,'organizations_active',v_active),
    updated_at=now() where id=p_operation returning * into v_op;
  return to_jsonb(v_op) || jsonb_build_object('applied_now', true);
end $$;


--
-- Name: fn_extensions_guard_core_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_guard_core_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status='dispatched' then
    perform pg_advisory_xact_lock(255,1);
    if exists (select 1 from public.extension_operations where kind in ('install','update') and status='preparing') then
      raise exception using errcode='P0001',message='extension_preparation_in_progress';
    end if;
  end if;
  return new;
end $$;


--
-- Name: fn_extensions_installation_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_installation_counts(p_actor uuid) RETURNS TABLE(installation_id uuid, active_organizations integer, awaiting_reactivation integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform public.fn_extensions_assert_actor(p_actor);
  return query
    select e.installation_id,
      (count(*) filter (where e.enabled))::integer,
      (count(*) filter (where not e.enabled and e.deactivated_by_removal_at is not null))::integer
    from public.organization_extensions e
    group by e.installation_id;
end $$;


--
-- Name: fn_extensions_permissoes_validas(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_permissoes_validas(p_permissions jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_permissions is not null
    and jsonb_typeof(p_permissions) = 'array'
    and jsonb_array_length(p_permissions) between 1 and 6
    and not exists (
      select 1 from jsonb_array_elements(p_permissions) e
      where jsonb_typeof(e.value) <> 'string'
         or e.value #>> '{}' not in (
              'navigation.tasks', 'navigation.inbox', 'navigation.kanban',
              'navigation.contacts', 'navigation.agenda', 'navigation.radar')
    )
    and (select count(distinct e.value) from jsonb_array_elements(p_permissions) e)
        = jsonb_array_length(p_permissions);
$$;


--
-- Name: fn_extensions_prepare_install(uuid, uuid, uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_prepare_install(p_actor uuid, p_operation uuid, p_catalog uuid, p_publisher text, p_name text, p_version text, p_expected_installation_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request jsonb := jsonb_build_object('kind','install','actor',p_actor,'catalog',p_catalog,'publisher',p_publisher,
    'name',p_name,'version',p_version,'expected_installation_revision',p_expected_installation_revision);
  v_op public.extension_operations; v_catalog public.extension_catalogs; v_entry jsonb;
  v_install public.extension_installations; v_current public.extension_artifacts; v_previous public.extension_artifacts;
  v_kind text; v_from jsonb := jsonb_build_object('from_revision', null);
begin
  perform public.fn_extensions_assert_actor(p_actor);
  if p_operation is null or p_catalog is null or p_publisher is null or p_name is null or p_version is null
    or p_expected_installation_revision < 1 then
    raise exception using errcode='P0001',message='extension_invalid_input';
  end if;
  perform pg_advisory_xact_lock(255,1);
  perform public.fn_extensions_assert_actor(p_actor);
  perform pg_advisory_xact_lock(hashtextextended(p_operation::text,255));
  perform public.fn_extensions_assert_actor(p_actor);
  select * into v_op from public.extension_operations where id=p_operation;
  if found then
    if v_op.request_fingerprint <> public.fn_extensions_fingerprint(v_request) then
      raise exception using errcode='P0001',message='extension_idempotency_conflict';
    end if;
    return to_jsonb(v_op) || jsonb_build_object('applied_now', false);
  end if;
  if public.fn_extensions_core_update_in_progress() then
    raise exception using errcode='P0001',message='extension_core_update_in_progress';
  end if;
  select * into v_catalog from public.extension_catalogs where id=p_catalog;
  if not found then raise exception using errcode='P0001',message='extension_catalog_not_found'; end if;
  select value into v_entry from jsonb_array_elements(v_catalog.snapshot->'entries')
    where value->>'publisher'=p_publisher and value->>'name'=p_name and value->>'version'=p_version;
  if not found then raise exception using errcode='P0001',message='extension_entry_not_found'; end if;
  select * into v_install from public.extension_installations
    where catalog_id=p_catalog and publisher=p_publisher and name=p_name;
  if v_install.revision is distinct from p_expected_installation_revision then
    raise exception using errcode='P0001',message='extension_version_changed';
  end if;
  if exists (select 1 from public.extension_operations where kind in ('install','update') and status='preparing'
    and catalog_id=p_catalog and publisher=p_publisher and name=p_name) then
    raise exception using errcode='P0001',message='extension_preparation_in_progress';
  end if;
  if v_install.id is not null then
    select * into v_current from public.extension_artifacts where id=v_install.artifact_id;
    select * into v_previous from public.extension_artifacts where id=v_install.previous_artifact_id;
    -- A mesma vers??o com outro digest ?? conflito contra o vigente, o anterior e a linha removida.
    if (v_install.version = p_version and v_current.sha256 <> v_entry->>'sha256')
      or (v_previous.id is not null and v_previous.manifest->>'version' = p_version
        and v_previous.sha256 <> v_entry->>'sha256') then
      raise exception using errcode='P0001',message='extension_version_conflict';
    end if;
    v_from := jsonb_build_object('from_revision',v_install.revision,'from_artifact_id',v_install.artifact_id,
      'from_version',v_install.version);
    if v_install.removed_at is null and v_install.version = p_version then
      insert into public.extension_operations(id,kind,status,actor_id,catalog_id,installation_id,publisher,name,version,
        request,request_fingerprint,admission_revision,admission_digest,entry,result)
        values(p_operation,'install','completed',p_actor,p_catalog,v_install.id,p_publisher,p_name,p_version,v_request,
          public.fn_extensions_fingerprint(v_request),v_catalog.revision,v_catalog.digest,v_entry,
          jsonb_build_object('installation',to_jsonb(v_install),'to_artifact_id',v_install.artifact_id))
        returning * into v_op;
      return to_jsonb(v_op) || jsonb_build_object('applied_now', false);
    end if;
  end if;
  if v_install.id is not null and v_install.removed_at is null then
    v_kind := 'update';
  else
    v_kind := 'install';
    -- A prepara????o de update n??o conta: ela n??o cria identidade.
    if (select count(*) from public.extension_installations where removed_at is null) +
      (select count(*) from public.extension_operations where kind='install' and status='preparing') >= 128 then
      raise exception using errcode='P0001',message='extension_installation_limit';
    end if;
  end if;
  insert into public.extension_operations(id,kind,status,actor_id,catalog_id,installation_id,publisher,name,version,
    request,request_fingerprint,admission_revision,admission_digest,entry,result)
    values(p_operation,v_kind,'preparing',p_actor,p_catalog,v_install.id,p_publisher,p_name,p_version,v_request,
      public.fn_extensions_fingerprint(v_request),v_catalog.revision,v_catalog.digest,v_entry,v_from)
    returning * into v_op;
  return to_jsonb(v_op) || jsonb_build_object('applied_now', true);
end $$;


--
-- Name: fn_extensions_remove_installation(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_remove_installation(p_actor uuid, p_operation uuid, p_installation uuid, p_expected_installation_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request jsonb := jsonb_build_object('kind','removal','actor',p_actor,'installation',p_installation,
    'expected_installation_revision',p_expected_installation_revision);
  v_op public.extension_operations; v_install public.extension_installations; v_from public.extension_installations;
  v_orgs uuid[];
begin
  perform public.fn_extensions_assert_actor(p_actor);
  if p_operation is null or p_installation is null or p_expected_installation_revision is null
    or p_expected_installation_revision < 1 then
    raise exception using errcode='P0001',message='extension_invalid_input';
  end if;
  perform pg_advisory_xact_lock(255,1);
  perform public.fn_extensions_assert_actor(p_actor);
  perform pg_advisory_xact_lock(hashtextextended(p_operation::text,255));
  perform public.fn_extensions_assert_actor(p_actor);
  select * into v_op from public.extension_operations where id=p_operation;
  if found then
    if v_op.request_fingerprint <> public.fn_extensions_fingerprint(v_request) then
      raise exception using errcode='P0001',message='extension_idempotency_conflict';
    end if;
    return to_jsonb(v_op) || jsonb_build_object('applied_now', false);
  end if;
  select * into v_install from public.extension_installations where id=p_installation for update;
  if not found then raise exception using errcode='P0001',message='extension_installation_not_found'; end if;
  if v_install.removed_at is not null then raise exception using errcode='P0001',message='extension_removed'; end if;
  if exists (select 1 from public.extension_operations where kind in ('install','update') and status='preparing'
    and catalog_id=v_install.catalog_id and publisher=v_install.publisher and name=v_install.name) then
    raise exception using errcode='P0001',message='extension_preparation_in_progress';
  end if;
  if v_install.revision <> p_expected_installation_revision then
    raise exception using errcode='P0001',message='extension_version_changed';
  end if;
  v_from := v_install;
  -- A instala????o ANTES dos v??nculos: na ordem inversa, a corrida com a configura????o d?? impasse.
  update public.extension_installations set removed_at=now(), removed_by=p_actor, revision=revision+1
    where id=p_installation returning * into v_install;
  with desligados as (
    update public.organization_extensions set enabled=false, revision=revision+1, updated_by=p_actor, updated_at=now(),
      deactivated_by_removal_at=now()
    where installation_id=p_installation and enabled
    returning organization_id)
  select coalesce(array_agg(organization_id order by organization_id), array[]::uuid[]) into v_orgs from desligados;
  insert into public.extension_operations(id,kind,status,actor_id,catalog_id,installation_id,publisher,name,version,
    request,request_fingerprint,result)
    values(p_operation,'removal','completed',p_actor,v_install.catalog_id,v_install.id,v_install.publisher,v_install.name,
      v_from.version,v_request,public.fn_extensions_fingerprint(v_request),
      jsonb_build_object('installation',to_jsonb(v_install),'from_revision',v_from.revision,'from_artifact_id',v_from.artifact_id,
        'from_version',v_from.version,'organizations_disabled',to_jsonb(v_orgs),
        'organizations_disabled_count',coalesce(array_length(v_orgs,1),0)))
    returning * into v_op;
  return to_jsonb(v_op) || jsonb_build_object('applied_now', true);
end $$;


--
-- Name: fn_extensions_revert_install(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_extensions_revert_install(p_actor uuid, p_operation uuid, p_installation uuid, p_expected_installation_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request jsonb := jsonb_build_object('kind','revert','actor',p_actor,'installation',p_installation,
    'expected_installation_revision',p_expected_installation_revision);
  v_op public.extension_operations; v_install public.extension_installations; v_from public.extension_installations;
  v_target public.extension_artifacts; v_active integer;
begin
  perform public.fn_extensions_assert_actor(p_actor);
  if p_operation is null or p_installation is null or p_expected_installation_revision is null
    or p_expected_installation_revision < 1 then
    raise exception using errcode='P0001',message='extension_invalid_input';
  end if;
  perform pg_advisory_xact_lock(255,1);
  perform public.fn_extensions_assert_actor(p_actor);
  perform pg_advisory_xact_lock(hashtextextended(p_operation::text,255));
  perform public.fn_extensions_assert_actor(p_actor);
  select * into v_op from public.extension_operations where id=p_operation;
  if found then
    if v_op.request_fingerprint <> public.fn_extensions_fingerprint(v_request) then
      raise exception using errcode='P0001',message='extension_idempotency_conflict';
    end if;
    return to_jsonb(v_op) || jsonb_build_object('applied_now', false);
  end if;
  if public.fn_extensions_core_update_in_progress() then
    raise exception using errcode='P0001',message='extension_core_update_in_progress';
  end if;
  select * into v_install from public.extension_installations where id=p_installation for update;
  if not found then raise exception using errcode='P0001',message='extension_installation_not_found'; end if;
  if v_install.removed_at is not null then raise exception using errcode='P0001',message='extension_removed'; end if;
  if exists (select 1 from public.extension_operations where kind in ('install','update') and status='preparing'
    and catalog_id=v_install.catalog_id and publisher=v_install.publisher and name=v_install.name) then
    raise exception using errcode='P0001',message='extension_preparation_in_progress';
  end if;
  if v_install.revision <> p_expected_installation_revision then
    raise exception using errcode='P0001',message='extension_version_changed';
  end if;
  if v_install.previous_artifact_id is null then
    raise exception using errcode='P0001',message='extension_no_previous_version';
  end if;
  select * into v_target from public.extension_artifacts where id=v_install.previous_artifact_id;
  -- Desfazer tem a mesma regra: voltar a uma vers??o com outro conjunto de portas mudaria em
  -- sil??ncio o que a organiza????o aceitou. Quem precisa disso reinstala e reativa.
  if v_target.manifest->'permissions' is distinct from
     (select manifest->'permissions' from public.extension_artifacts where id=v_install.artifact_id) then
    raise exception using errcode='P0001',message='extension_permissions_changed';
  end if;
  v_from := v_install;
  update public.extension_installations set artifact_id=previous_artifact_id, previous_artifact_id=artifact_id,
    version=v_target.manifest->>'version', revision=revision+1 where id=p_installation returning * into v_install;
  select count(*)::integer into v_active from public.organization_extensions where installation_id=p_installation and enabled;
  insert into public.extension_operations(id,kind,status,actor_id,catalog_id,installation_id,publisher,name,version,
    request,request_fingerprint,result)
    values(p_operation,'revert','completed',p_actor,v_install.catalog_id,v_install.id,v_install.publisher,v_install.name,
      v_install.version,v_request,public.fn_extensions_fingerprint(v_request),
      jsonb_build_object('installation',to_jsonb(v_install),'from_revision',v_from.revision,'from_artifact_id',v_from.artifact_id,
        'from_version',v_from.version,'to_artifact_id',v_install.artifact_id,'to_version',v_install.version,
        'organizations_active',v_active))
    returning * into v_op;
  return to_jsonb(v_op) || jsonb_build_object('applied_now', true);
end $$;


--
-- Name: fn_finalizar_comanda(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_finalizar_comanda(p_org uuid, p_sale uuid, p_payment_method uuid, p_loyalty_points integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sale       public.sales%rowtype;
  v_conta      uuid;
  v_plano      uuid;
  v_total      bigint;
  v_item       record;
  v_entry      uuid;
begin
  if auth.uid() is null or not public.fn_role_at_least(p_org, 'agent') then
    raise exception 'comanda_forbidden' using errcode = '42501';
  end if;

  -- FOR UPDATE: duas finaliza????es simult??neas da mesma comanda geravam
  -- lan??amento em dobro. O lock ?? o que torna esta fun????o idempotente de fato,
  -- e n??o s?? na inten????o.
  select * into v_sale from public.sales
   where id = p_sale and organization_id = p_org
   for update;

  if not found then
    raise exception 'comanda_nao_encontrada' using errcode = 'P0002';
  end if;
  if v_sale.status = 'finalized' then
    -- N??o ?? erro: quem chamou duas vezes recebe o mesmo desfecho.
    return jsonb_build_object('sale_id', v_sale.id, 'ja_finalizada', true);
  end if;
  if v_sale.status = 'cancelled' then
    raise exception 'comanda_cancelada' using errcode = '22023';
  end if;

  select account_id into v_conta from public.payment_methods
   where id = p_payment_method and organization_id = p_org and is_active;
  if not found then
    raise exception 'forma_de_pagamento_invalida' using errcode = '22023';
  end if;
  if v_conta is null then
    -- A forma existe e n??o diz para onde o dinheiro vai. Recusar aqui ?? melhor
    -- que escolher uma conta por conta pr??pria.
    raise exception 'forma_sem_conta'
      using errcode = '22023',
            hint = 'Esta forma de pagamento ainda n??o tem conta de destino. Defina em Configura????es ??? Financeiro.';
  end if;

  select coalesce(sum(total_cents), 0) into v_total
    from public.sale_items where sale_id = p_sale;
  v_total := greatest(v_total - coalesce(v_sale.discount_cents, 0), 0);

  -- (1) a venda
  update public.sales
     set status = 'finalized',
         finalized_at = now(),
         payment_method_id = p_payment_method,
         total_cents = v_total
   where id = p_sale;

  -- (2) a comiss??o por item, com o percentual CONGELADO na inclus??o
  for v_item in
    select * from public.sale_items where sale_id = p_sale and attendant_user_id is not null
  loop
    insert into public.commissions
      (organization_id, sale_item_id, attendant_user_id, percent, amount_cents)
    values (
      p_org, v_item.id, v_item.attendant_user_id, v_item.commission_percent,
      -- Sobre o item, NUNCA sobre o desconto da comanda: um desconto de caixa
      -- n??o pode reduzir o que quem atendeu combinou.
      floor(v_item.total_cents * v_item.commission_percent / 100.0)
    )
    on conflict (sale_item_id) do nothing;
  end loop;

  -- (3) a entrada na conta que a FORMA DE PAGAMENTO determina
  select id into v_plano from public.account_plans
   where organization_id = p_org and direction = 'in' and is_active
   order by created_at limit 1;

  insert into public.financial_entries
    (organization_id, account_id, account_plan_id, sale_id, direction, amount_cents,
     currency, description, status, paid_at, origin, created_by_user_id)
  values (
    p_org, v_conta, v_plano, p_sale, 'in', greatest(v_total, 1),
    v_sale.currency, format('Comanda #%s', v_sale.number), 'paid', now(), 'sale', auth.uid()
  )
  returning id into v_entry;

  -- (4) o ponto de fidelidade, idempotente pela chave da comanda
  if p_loyalty_points > 0 and v_sale.contact_id is not null then
    insert into public.loyalty_ledger
      (organization_id, contact_id, points, reason, sale_id, idempotency_key, created_by_user_id)
    values (
      p_org, v_sale.contact_id, p_loyalty_points, 'Comanda finalizada', p_sale,
      format('sale:%s', p_sale), auth.uid()
    )
    on conflict do nothing;
  end if;

  -- (5) o agendamento conclui ??? e S?? se ainda estiver de p??.
  if v_sale.appointment_id is not null then
    update public.calendar_appointments
       set status = 'completed', outcome_recorded_at = now()
     where id = v_sale.appointment_id
       and organization_id = p_org
       -- A guarda que o sistema de origem n??o tinha em todos os caminhos:
       -- cancelado e faltou s??o desfechos DECIDIDOS, e faturar n??o os desfaz.
       and status not in ('cancelled', 'no_show');
  end if;

  return jsonb_build_object(
    'sale_id', v_sale.id,
    'number', v_sale.number,
    'total_cents', v_total,
    'entry_id', v_entry
  );
end $$;


--
-- Name: FUNCTION fn_finalizar_comanda(p_org uuid, p_sale uuid, p_payment_method uuid, p_loyalty_points integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_finalizar_comanda(p_org uuid, p_sale uuid, p_payment_method uuid, p_loyalty_points integer) IS 'As seis coisas numa transa????o: venda, comiss??o por item, entrada na conta da forma de pagamento, ponto de fidelidade e conclus??o do agendamento. Idempotente sob FOR UPDATE.';


--
-- Name: fn_finish_channel_connection(uuid, uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_finish_channel_connection(p_org uuid, p_receipt uuid, p_lease uuid, p_status text, p_reason text DEFAULT NULL::text, p_created boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare receipt public.channel_connection_requests; channel public.channel_sessions;
begin
 select * into receipt from public.channel_connection_requests where organization_id=p_org and id=p_receipt for update;
 if not found or receipt.state<>'processing' or receipt.lease_token<>p_lease
   or receipt.lease_until<=now()
 then raise exception 'connection_lease_lost' using errcode='55P03';end if;
 if p_status='remote_created' then
  update public.channel_connection_requests set remote_created=true,updated_at=now() where organization_id=p_org and id=p_receipt;
  return '{}'::jsonb;
 end if;
 if p_status not in('STARTING','SCAN_QR_CODE','WORKING','FAILED') then raise exception 'connection_invalid_status' using errcode='22023';end if;
 update public.channel_sessions set status=p_status,status_reason=left(p_reason,200),last_status_change_at=now(),
  consecutive_health_fails=case when p_status='FAILED' then consecutive_health_fails else 0 end,
  archived_at=case when p_status<>'FAILED' then null else archived_at end,
  phone_number=case when archived_at is not null and p_status<>'FAILED' then null else phone_number end
  where organization_id=p_org and id=receipt.channel_session_id returning * into channel;
 if not found then raise exception 'connection_reservation_missing' using errcode='P0002';end if;
 update public.channel_connection_requests set state=case when p_status='FAILED' then 'failed' else 'succeeded' end,
  remote_created=remote_created or p_created,updated_at=now() where organization_id=p_org and id=p_receipt;
 return to_jsonb(channel);
end;
$$;


--
-- Name: fn_followup_apply_step(uuid, uuid, bigint, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_followup_apply_step(p_org uuid, p_id uuid, p_revision bigint, p_patch jsonb, p_event jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare revision bigint; contact uuid;
begin
 if p_event ? 'job_id' then
  select contact_id into contact from public.followup_enrollments where organization_id=p_org and id=p_id;
  perform public.fn_service_lock(p_org,contact);
  perform 1 from public.job_queue where id=(p_event->>'job_id')::uuid and organization_id=p_org for update;
  if not public.fn_followup_claim_current(p_org,(p_event->>'job_id')::uuid,p_event->'job_claim'->>'worker_id',(p_event->'job_claim'->>'acquired_at')::timestamptz)
   or not public.fn_followup_job_current(p_org,(p_event->>'job_id')::uuid,p_id,p_event->>'node_id') then
   raise exception 'followup_job_stale' using errcode='40001';
  end if;
 end if;
 revision:=public.fn_followup_patch(p_org,p_id,p_revision,p_patch);
 insert into public.followup_enrollment_events(organization_id,enrollment_id,node_id,event_type,payload,idempotency_key)
  values(p_org,p_id,p_event->>'node_id',p_event->>'event_type',coalesce(p_event->'payload','{}'::jsonb),p_event->>'idempotency_key');
 return revision;
end; $$;


--
-- Name: fn_followup_claim_current(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_followup_claim_current(p_org uuid, p_job uuid, p_worker text, p_acquired_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 select exists(select 1 from public.job_queue where organization_id=p_org and id=p_job
  and kind='followup_turn' and status='running' and locked_by=p_worker and locked_at=p_acquired_at);
$$;


--
-- Name: fn_followup_generation_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_followup_generation_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
begin
 if tg_table_name='job_queue' then
  if auth.uid() is not null and ((tg_op<>'DELETE' and new.kind='followup_turn') or (tg_op<>'INSERT' and old.kind='followup_turn')) then
   raise exception 'followup_job_internal' using errcode='42501';
  end if;
  if tg_op='UPDATE' and old.kind='followup_turn' then
   if new.organization_id<>old.organization_id or new.contact_id is distinct from old.contact_id or new.kind<>old.kind
    or new.payload->'followup_enrollment_id' is distinct from old.payload->'followup_enrollment_id'
    or new.payload->'node_id' is distinct from old.payload->'node_id'
    or new.payload->'source_step_key' is distinct from old.payload->'source_step_key'
   then raise exception 'followup_job_origin_immutable' using errcode='42501'; end if;
  end if;
 elsif auth.uid() is not null and ((tg_op<>'DELETE' and new.idempotency_key ~ ':[0-9]+$') or (tg_op<>'INSERT' and old.idempotency_key ~ ':[0-9]+$')) then
  raise exception 'followup_step_internal' using errcode='42501';
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end; $_$;


--
-- Name: fn_followup_inline_settle(uuid, uuid, text, boolean, text, timestamp with time zone, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_followup_inline_settle(p_org uuid, p_id uuid, p_worker text, p_done boolean, p_error text DEFAULT NULL::text, p_retry_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_hold boolean DEFAULT false, p_acquired_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare j public.job_queue;
begin
 update public.job_queue set
  status=case when p_done then 'done' when p_hold then 'pending' when attempts>=max_attempts then 'dead' else 'pending' end,
  attempts=case when p_hold then greatest(0,attempts-1) else attempts end,
  run_after=coalesce(p_retry_at,now()+interval '1 minute'),locked_by=null,locked_at=null,last_error=left(p_error,400)
 where organization_id=p_org and id=p_id and kind='followup_turn' and status='running' and locked_by=p_worker and locked_at=p_acquired_at returning * into j;
 if not found then return false; end if;
 if j.status='dead' then
  insert into public.agent_inbox_items(organization_id,kind,severity,title,body,ref_kind,ref_id)
   values(p_org,'job_dead','critical','O acompanhamento n??o conseguiu enviar a mensagem',
    'Abra o acompanhamento e confira o canal. Motivo: '||coalesce(j.last_error,'envio indispon??vel'),'job_queue',j.id);
 end if;
 return true;
end; $$;


--
-- Name: fn_followup_job_current(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_followup_job_current(p_org uuid, p_job uuid, p_enrollment uuid, p_node text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
 select exists(select 1 from public.job_queue j
  join public.followup_enrollments e on e.id=p_enrollment and e.organization_id=j.organization_id and e.contact_id=j.contact_id
  join public.followup_enrollment_events origin on origin.organization_id=e.organization_id and origin.enrollment_id=e.id
   and origin.node_id=p_node and origin.idempotency_key=j.payload->>'source_step_key'
   and origin.event_type in ('turn_enqueued','classify_enqueued')
  where j.id=p_job and j.organization_id=p_org and j.kind='followup_turn' and j.status in ('pending','running')
   and j.payload->>'followup_enrollment_id'=p_enrollment::text and j.payload->>'node_id'=p_node
   and origin.idempotency_key = origin.node_id||':'||substring(origin.idempotency_key from ':([0-9]+)$')
   and public.fn_appointment_enrollment_current(p_org,p_enrollment,p_node)
   and not exists(select 1 from public.followup_enrollment_events later
    where later.organization_id=p_org and later.enrollment_id=e.id
     and later.idempotency_key=later.node_id||':'||substring(later.idempotency_key from ':([0-9]+)$')
     and substring(later.idempotency_key from ':([0-9]+)$')::numeric > substring(origin.idempotency_key from ':([0-9]+)$')::numeric
     and not (later.node_id=p_node and later.event_type='action_recheck')));
$_$;


--
-- Name: fn_followup_patch(uuid, uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_followup_patch(p_org uuid, p_id uuid, p_revision bigint, p_patch jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare current public.followup_enrollments; patched public.followup_enrollments; contact uuid;
begin
 select contact_id into contact from public.followup_enrollments where id=p_id and organization_id=p_org;
 if not found then raise exception 'followup_stale' using errcode='P0001'; end if;
 perform public.fn_service_lock(p_org,contact);
 select * into current from public.followup_enrollments where id=p_id and organization_id=p_org for update;
 if current.contact_id is distinct from contact or current.revision is distinct from p_revision then raise exception 'followup_stale' using errcode='P0001'; end if;
 if p_patch->>'status' in ('active','waiting_reply') and current.appointment_revision is not null and not public.fn_appointment_enrollment_current(p_org,p_id,current.current_node_id) then raise exception 'followup_stale' using errcode='P0001'; end if;
 select * into patched from jsonb_populate_record(current,p_patch);
 update public.followup_enrollments set status=patched.status,current_node_id=patched.current_node_id,next_eval_at=patched.next_eval_at,
  claimed_until=patched.claimed_until,attempts=patched.attempts,last_error=patched.last_error,steps_taken=patched.steps_taken,
  outcome=patched.outcome,cancel_reason=patched.cancel_reason,completed_at=patched.completed_at,timing_plan=patched.timing_plan
 where organization_id=p_org and id=p_id returning revision into p_revision;
 return p_revision;
end; $$;


--
-- Name: fn_followup_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_followup_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 -- Origem da recupera????o ?? imut??vel, inclusive para quem pode editar o fluxo.
 -- S?? o desaparecimento real da FK permite apagar a refer??ncia, cancelando-o.
 if old.appointment_revision is not null then
  new.appointment_revision:=old.appointment_revision;
  if new.appointment_id is null and not exists(select 1 from public.calendar_appointments where organization_id=old.organization_id and id=old.appointment_id) then
   new.status:='cancelled';new.cancel_reason:='O compromisso foi removido.';new.next_eval_at:=null;new.claimed_until:=null;new.completed_at:=now();
  else new.appointment_id:=old.appointment_id; end if;
  if new.contact_id is distinct from old.contact_id then
   new.status:='cancelled';new.cancel_reason:='O contato do compromisso mudou.';new.next_eval_at:=null;new.claimed_until:=null;new.completed_at:=now();
  end if;
 end if;
 if new.appointment_revision is not null and new.status in ('active','waiting_reply','paused_handoff','paused_manual') then
  -- P0001, n??o 40001: 40001 ?? serialization_failure e o cliente retenta para
  -- sempre. followup_stale ?? permanente. Medido: 6000 erros/min, CPU 100%, 24h.
  if old.status not in ('active','waiting_reply','paused_handoff','paused_manual') or not exists(
   select 1 from public.calendar_appointments a join public.appointment_recovery_receipts r
    on r.organization_id=a.organization_id and r.appointment_id=a.id and r.appointment_revision=a.revision
   where a.organization_id=new.organization_id and a.id=new.appointment_id and a.revision=new.appointment_revision
    and a.status='no_show' and a.contact_id=new.contact_id and r.result='started' and r.invalidated_at is null
  ) then raise exception 'followup_stale' using errcode='P0001'; end if;
 end if;
 new.revision:=old.revision+1; return new;
end; $$;


--
-- Name: fn_gasto_de_ia_do_mes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_gasto_de_ia_do_mes(p_org uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(sum(cost_cents), 0)::numeric
    from public.llm_calls
   where organization_id = p_org
     and created_at >= date_trunc('month', now());
$$;


--
-- Name: FUNCTION fn_gasto_de_ia_do_mes(p_org uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_gasto_de_ia_do_mes(p_org uuid) IS 'Gasto de IA da organiza????o no m??s corrente, em centavos de D??LAR (llm_calls.cost_cents vem de pricing.ts, que calcula em USD). ?? a ??NICA defini????o de gasto do produto: o gate a chama dentro de SQL_ORCAMENTO (lib/agent-engine/edge/llm/orcamento.ts), a tela a chama por RPC e o painel de sa??de por tenant a chama. O dashboard de plataforma (app/api/v1/admin/dashboard/kpis) AINDA l?? ai_budgets.current_month_consumed_cents, um contador acumulado que nada zera, e por isso pode divergir ??? a diverg??ncia est?? declarada naquele arquivo e o alerta de l?? nunca ?? critical. Query inline de sum(cost_cents) em outro lugar ?? uma segunda r??gua, e a segunda r??gua sempre diverge ??? vigiado por tests/unit/orcamento-uma-regua-de-gasto.test.ts. security invoker: recebe a organiza????o por argumento e n??o valida membership, ent??o definer aqui seria leitura cross-tenant.';


--
-- Name: fn_google_appointment(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_appointment(p_org uuid, p_id uuid, p_action text, p_args jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.calendar_appointments; c public.calendar_connection_calendars; conn public.calendar_connections;
 contact uuid; claim jsonb:=p_args->'claim'; result jsonb; b jsonb; changed boolean; remote jsonb;
begin
 select contact_id into contact from public.calendar_appointments where organization_id=p_org and id=p_id;
 if not found then raise exception 'appointment_not_found' using errcode='P0002';end if;
 if contact is not null then perform public.fn_service_lock(p_org,contact);end if;
 -- Sele????o/reserva compartilham membership antes dos locks de calend??rio/appointment.
 perform 1 from public.user_organizations m join public.calendar_appointments x on x.organization_id=m.organization_id and x.owner_user_id=m.user_id
  where x.organization_id=p_org and x.id=p_id for update of m;
 if p_args?'calendar_fence' then
  perform public.fn_google_calendar_fence(p_org,(p_args->'calendar_fence'->>'id')::uuid,p_args->'calendar_fence'->'claim',p_args->'calendar_fence'->'cursor');
 end if;
 select * into a from public.calendar_appointments where organization_id=p_org and id=p_id for update;
 if a.contact_id is distinct from contact then raise exception 'appointment_stale' using errcode='40001';end if;
 if contact is not null and exists(select 1 from public.contacts where organization_id=p_org and id=contact and is_anonymized) then
  if p_action='claim' then return jsonb_build_object('terminal','redacted');end if;
  raise exception 'google_contact_redacted' using errcode='42501';end if;
 if not exists(select 1 from public.user_organizations where organization_id=p_org and user_id=a.owner_user_id and revoked_at is null) then
  raise exception 'google_owner_unavailable' using errcode='42501';end if;
 if p_action='claim' then
  if a.google_claim_until>clock_timestamp() then return null;end if;
  if a.google_event_id is null and a.status<>'cancelled' then
   select k.* into c from public.calendar_connection_calendars k join public.calendar_connections x on x.id=k.connection_id and x.organization_id=k.organization_id
    where k.organization_id=p_org and x.user_id=a.owner_user_id and k.is_destination;
   if not found or (select count(*) from public.calendar_connection_calendars k join public.calendar_connections x on x.id=k.connection_id and x.organization_id=k.organization_id where k.organization_id=p_org and x.user_id=a.owner_user_id and k.is_destination)<>1 then
    update public.calendar_appointments set google_sync_error='Escolha uma agenda de destino nas configura????es.',google_next_attempt_at=now()+interval '15 minutes' where organization_id=p_org and id=p_id;return null;
   end if;
   if not c.available or c.access_role not in ('owner','writer') then
    update public.calendar_appointments set google_sync_error='A agenda de destino n??o permite publica????o. Confira o acesso nas configura????es.',google_next_attempt_at=now()+interval '15 minutes' where organization_id=p_org and id=p_id;return null;end if;
   update public.calendar_appointments set google_connection_id=c.connection_id,google_calendar_id=c.external_calendar_id,
    google_event_id='deskcommapp'||replace(id::text,'-',''),google_pending_write='{"reservation":true}'::jsonb where organization_id=p_org and id=p_id returning * into a;
  end if;
  update public.calendar_appointments set google_claim_token=gen_random_uuid(),google_claim_epoch=google_claim_epoch+1,
   google_claim_until=clock_timestamp()+interval '90 seconds' where organization_id=p_org and id=p_id returning * into a;
 else
  if a.google_claim_token is distinct from (claim->>'token')::uuid or a.google_claim_epoch::text is distinct from claim->>'epoch'
   or a.google_claim_until is null or a.google_claim_until<=clock_timestamp() then raise exception 'google_stale' using errcode='40001';end if;
  if p_action='renew' then
   if a.revision::text is distinct from p_args->>'revision' or a.google_local_revision::text is distinct from p_args->>'local_revision' then raise exception 'google_stale' using errcode='40001';end if;
   if not exists(select 1 from public.calendar_connections x join public.calendar_connection_calendars k on k.organization_id=x.organization_id and k.connection_id=x.id
    where x.organization_id=p_org and x.id=a.google_connection_id and x.user_id=a.owner_user_id and x.status='healthy' and k.external_calendar_id=a.google_calendar_id and k.available and k.access_role in ('writer','owner')) then raise exception 'google_connection_unavailable' using errcode='42501';end if;
   update public.calendar_appointments set google_claim_until=clock_timestamp()+interval '90 seconds' where organization_id=p_org and id=p_id returning * into a;
  elsif p_action='release' then
   update public.calendar_appointments set google_claim_token=null,google_claim_until=null where organization_id=p_org and id=p_id;return 'true';
  else
   if a.revision::text is distinct from p_args->>'revision' or a.google_local_revision::text is distinct from p_args->>'local_revision'
    or a.google_event_id is distinct from p_args->>'event_id' or a.google_connection_id::text is distinct from p_args->>'connection_id'
    or a.google_calendar_id is distinct from p_args->>'calendar_id' then raise exception 'google_stale' using errcode='40001';end if;
   if p_action='error' then
    update public.calendar_appointments set google_sync_error=left(p_args->>'message',200),google_next_attempt_at=now()+interval '15 minutes',
     meeting_state=case when meeting_state='pending' and meeting_attempts>=19 then 'failed' else meeting_state end,
     meeting_last_error=case when meeting_state='pending' then 'unknown' else meeting_last_error end,
     meeting_attempts=meeting_attempts+case when meeting_state='pending' then 1 else 0 end,
     meeting_next_attempt_at=case when meeting_state='pending' then now()+make_interval(secs=>least(900,15*power(2,least(meeting_attempts,6)))::double precision+floor(random()*5)) else meeting_next_attempt_at end
     where organization_id=p_org and id=p_id;return 'true';end if;
   if a.google_event_id is not null then
    select * into conn from public.calendar_connections where organization_id=p_org and id=a.google_connection_id and user_id=a.owner_user_id;
    select * into c from public.calendar_connection_calendars where organization_id=p_org and connection_id=a.google_connection_id and external_calendar_id=a.google_calendar_id;
    if conn.id is null or conn.status<>'healthy' or c.id is null or not c.available then raise exception 'google_connection_unavailable' using errcode='42501';end if;
   end if;
   if p_action='meet' then
    perform public.fn_meet_observe(p_org,p_id,p_args);
    select * into a from public.calendar_appointments where organization_id=p_org and id=p_id;
   elsif p_action='prepare' then
    if c.access_role not in ('owner','writer') or (a.google_pending_write is not null and a.google_pending_write<>'{"reservation":true}'::jsonb) or a.google_conflict is not null then raise exception 'google_write_unavailable' using errcode='40001';end if;
    if p_args->'operation'?'conference_request_id' and (a.meeting_request_id is distinct from (p_args->'operation'->>'conference_request_id')::uuid or a.meeting_state<>'pending' or a.meeting_received_at is not null or a.status='cancelled') then raise exception 'meet_stale' using errcode='40001';end if;
    update public.calendar_appointments set meeting_requested_at=case when p_args->'operation'?'conference_request_id' then coalesce(meeting_requested_at,now()) else meeting_requested_at end,google_pending_write=p_args->'operation' where organization_id=p_org and id=p_id;return 'true';
   elsif p_action='idle' then
    update public.calendar_appointments set google_next_attempt_at=now()+interval '15 minutes' where organization_id=p_org and id=p_id;return 'true';
   elsif p_action='commit' then
    result:=p_args->'result'; b:=result->'base';remote:=result->'remote';
    if result?'operation_id' and a.google_pending_write->>'operation_id' is distinct from result->>'operation_id' then raise exception 'google_stale' using errcode='40001';end if;
    if result?'apply_remote' then
     if a.status not in ('pending','confirmed') then raise exception 'google_outcome_protected' using errcode='40001';end if;
     if not coalesce((remote->>'cancelled')::boolean,false) and exists(select 1 from public.calendar_appointments other
      where other.organization_id=p_org and other.owner_user_id=a.owner_user_id and other.id<>a.id and other.status in ('pending','confirmed')
      and other.starts_at<(remote->>'ends_at')::timestamptz and other.ends_at>(remote->>'starts_at')::timestamptz) then
      return jsonb_build_object('overlap',true);end if;
     changed:=row(a.starts_at,a.ends_at,a.time_zone,a.status='cancelled') is distinct from row((remote->>'starts_at')::timestamptz,(remote->>'ends_at')::timestamptz,remote->>'time_zone',(remote->>'cancelled')::boolean);
     perform public.fn_appointment_change_core(p_org,p_id,a.revision,
      jsonb_build_object('starts_at',remote->>'starts_at','ends_at',remote->>'ends_at','time_zone',remote->>'time_zone')||
      case when (remote->>'cancelled')::boolean then '{"status":"cancelled","cancellation_reason":"Cancelado no Google"}'::jsonb else '{}'::jsonb end,true,b);
     if changed then
      insert into public.crm_lead_activities(organization_id,lead_id,contact_id,type,source_module,source_id,actor_kind,reason,payload)
       select p_org,l.lead_id,a.contact_id,case when (remote->>'cancelled')::boolean then 'appointment_cancelled' else 'appointment_rescheduled' end,
        'agenda',p_id,'system',case when (remote->>'cancelled')::boolean then 'Cancelado no Google' else 'Remarcado no Google' end,jsonb_build_object('origin','google','appointment_id',p_id,'resolution_actor_id',a.google_conflict->'resolution'->>'actor_id')
       from public.crm_lead_links l where l.organization_id=p_org and l.target_id=p_id and l.target_kind='appointment' group by l.lead_id;
     end if;
    end if;
    update public.calendar_appointments set
     google_base_projection=case when result?'base' then b else google_base_projection end,
     google_etag=case when result?'etag' then result->>'etag' else google_etag end,
     google_conflict=case when result?'conflict' then nullif(result->'conflict','null'::jsonb) else google_conflict end,
     google_pending_write=case when coalesce((result->>'retry_creation')::boolean,false) and a.google_base_projection is null and a.google_pending_write->>'method'='POST'
      then '{"reservation":true}'::jsonb when coalesce((result->>'clear_pending')::boolean,false) then null else google_pending_write end,
     google_synced_local_revision=case when coalesce((result->>'ack')::boolean,false) then a.google_local_revision else google_synced_local_revision end,
     google_synced_at=case when coalesce((result->>'ack')::boolean,false) then now() else google_synced_at end,
     google_sync_error=null,google_next_attempt_at=now()+interval '5 minutes'
     where organization_id=p_org and id=p_id returning * into a;
   else raise exception 'google_action_invalid' using errcode='22023';end if;
  end if;
 end if;
 return to_jsonb(a)||jsonb_build_object('revision',a.revision::text,'google_local_revision',a.google_local_revision::text,
  'google_synced_local_revision',a.google_synced_local_revision::text,'meeting_allowed_types',(select allowed_conference_types from public.calendar_connection_calendars where organization_id=p_org and connection_id=a.google_connection_id and external_calendar_id=a.google_calendar_id),'claim',jsonb_build_object('token',a.google_claim_token,'epoch',a.google_claim_epoch::text,'lease_until',a.google_claim_until));
end;$$;


--
-- Name: fn_google_calendar(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_calendar(p_org uuid, p_id uuid, p_action text, p_args jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.calendar_connection_calendars; cur jsonb; it jsonb; gen uuid; rebuild_full boolean; token text;
begin
 select * into c from public.calendar_connection_calendars where organization_id=p_org and id=p_id for update;
 if not found then raise exception 'google_calendar_not_found' using errcode='P0002';end if;
 if not exists(select 1 from public.calendar_connections x join public.user_organizations m on m.organization_id=x.organization_id and m.user_id=x.user_id
  where x.organization_id=p_org and x.id=c.connection_id and m.revoked_at is null and x.status='healthy') then raise exception 'google_connection_unavailable' using errcode='42501';end if;
 if p_action='claim' then
  if c.sync_claim_until>clock_timestamp() or not c.available then return null;end if;
  cur:=c.sync_cursor;
  if cur is null then
   rebuild_full:=c.sync_token is null or c.sync_coverage is null or (c.sync_coverage->>'completed_at')::timestamptz<now()-interval '24 hours';
   cur:=jsonb_build_object('generation',gen_random_uuid(),'mode',case when rebuild_full then 'full' else 'incremental' end,
    'base_sync_token',case when rebuild_full then null else c.sync_token end,'page_token',null,
    'window_start',case when rebuild_full then now()-interval '1 day' else (c.sync_coverage->>'window_start')::timestamptz end,
    'window_end',case when rebuild_full then now()+interval '90 days' else (c.sync_coverage->>'window_end')::timestamptz end);
  end if;
  update public.calendar_connection_calendars set sync_claim_token=gen_random_uuid(),sync_claim_epoch=sync_claim_epoch+1,
   sync_claim_until=clock_timestamp()+interval '90 seconds',sync_cursor=cur where organization_id=p_org and id=p_id returning * into c;
 else
  perform public.fn_google_calendar_fence(p_org,p_id,p_args->'claim',p_args->'cursor');
  if p_action='renew' then
   update public.calendar_connection_calendars set sync_claim_until=clock_timestamp()+interval '90 seconds' where organization_id=p_org and id=p_id returning * into c;
  elsif p_action='release' then
   update public.calendar_connection_calendars set sync_claim_token=null,sync_claim_until=null where organization_id=p_org and id=p_id;return 'true';
  elsif p_action='error' then
   update public.calendar_connection_calendars set sync_error=left(p_args->>'message',200),sync_next_attempt_at=now()+interval '15 minutes' where organization_id=p_org and id=p_id;return 'true';
  elsif p_action='reset' then
   update public.calendar_connection_calendars set sync_token=null,sync_cursor=null,sync_error='A ocupa????o est?? desatualizada. Reconstruindo a leitura.',sync_next_attempt_at=now()
    where organization_id=p_org and id=p_id;return 'true';
  elsif p_action='item' then
   it:=p_args->'item';gen:=(c.sync_cursor->>'generation')::uuid;
   -- O v??nculo ?? resolvido antes do cache/anti-eco, tamb??m quando s?? chega id.
   if exists(select 1 from public.calendar_appointments where organization_id=p_org and google_connection_id=c.connection_id and google_calendar_id=c.external_calendar_id and google_event_id=it->>'external_event_id') then
    delete from public.calendar_external_events where organization_id=p_org and connection_id=c.connection_id and external_calendar_id=c.external_calendar_id and external_event_id=it->>'external_event_id';
    return 'true';
   end if;
   insert into public.calendar_external_events(organization_id,connection_id,external_calendar_id,external_event_id,title,starts_at,ends_at,status,transparency,is_all_day,seen_generation,recurring_event_id,original_start_time)
    values(p_org,c.connection_id,c.external_calendar_id,it->>'external_event_id',null,(it->>'starts_at')::timestamptz,(it->>'ends_at')::timestamptz,
     it->>'status',coalesce(it->>'transparency','opaque'),coalesce((it->>'is_all_day')::boolean,false),gen,it->>'recurring_event_id',it->'original_start_time')
    on conflict(organization_id,connection_id,external_calendar_id,external_event_id) do update set title=null,starts_at=excluded.starts_at,ends_at=excluded.ends_at,
     status=excluded.status,transparency=excluded.transparency,is_all_day=excluded.is_all_day,seen_generation=excluded.seen_generation,
     recurring_event_id=coalesce(excluded.recurring_event_id,calendar_external_events.recurring_event_id),original_start_time=coalesce(excluded.original_start_time,calendar_external_events.original_start_time);
   return 'true';
  elsif p_action='page' then
   token:=p_args->>'next_page_token';
   if token is not null and token=c.sync_cursor->>'page_token' then raise exception 'google_cursor_no_progress' using errcode='22023';end if;
   if token is null then
    if coalesce(p_args->>'next_sync_token','')='' then raise exception 'google_checkpoint_missing' using errcode='22023';end if;
    if c.sync_cursor->>'mode'='full' then
     delete from public.calendar_external_events where organization_id=p_org and connection_id=c.connection_id and external_calendar_id=c.external_calendar_id
      and starts_at<(c.sync_cursor->>'window_end')::timestamptz and ends_at>(c.sync_cursor->>'window_start')::timestamptz
      and seen_generation is distinct from (c.sync_cursor->>'generation')::uuid and status<>'cancelled';
    end if;
    update public.calendar_connection_calendars set sync_token=p_args->>'next_sync_token',sync_cursor=null,last_sync_at=now(),sync_error=null,
     sync_coverage=case when c.sync_cursor->>'mode'='full' then c.sync_cursor-'page_token'-'base_sync_token'-'mode'||jsonb_build_object('completed_at',now()) else c.sync_coverage end,
     sync_next_attempt_at=now()+interval '15 minutes' where organization_id=p_org and id=p_id returning * into c;
   else
    update public.calendar_connection_calendars set sync_cursor=jsonb_set(sync_cursor,'{page_token}',to_jsonb(token)),sync_next_attempt_at=now() where organization_id=p_org and id=p_id returning * into c;
   end if;
  else raise exception 'google_action_invalid' using errcode='22023';end if;
 end if;
 return to_jsonb(c)||jsonb_build_object('claim',jsonb_build_object('token',c.sync_claim_token,'epoch',c.sync_claim_epoch::text,'lease_until',c.sync_claim_until));
end;$$;


--
-- Name: fn_google_calendar_fence(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_calendar_fence(p_org uuid, p_id uuid, p_claim jsonb, p_cursor jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.calendar_connection_calendars;
begin
 select * into c from public.calendar_connection_calendars where organization_id=p_org and id=p_id for update;
 if not found or not c.available or c.access_role not in ('owner','writer','reader','writerWithoutPrivateAccess') or c.sync_claim_token is distinct from (p_claim->>'token')::uuid
  or c.sync_claim_epoch::text is distinct from p_claim->>'epoch' or c.sync_claim_until<=clock_timestamp() or c.sync_claim_until is null
  or (p_cursor is not null and c.sync_cursor is distinct from p_cursor) then raise exception 'google_stale' using errcode='40001'; end if;
 if not exists(select 1 from public.calendar_connections x join public.user_organizations m on m.organization_id=x.organization_id and m.user_id=x.user_id
  where x.organization_id=p_org and x.id=c.connection_id and m.revoked_at is null and x.status='healthy') then raise exception 'google_connection_unavailable' using errcode='42501';end if;
end;$$;


--
-- Name: fn_google_catalog(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_catalog(p_org uuid, p_connection uuid, p_items jsonb, p_revision text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare conn public.calendar_connections; it jsonb; fresh boolean;
begin
 select * into conn from public.calendar_connections where organization_id=p_org and id=p_connection;
 if not found then raise exception 'google_connection_unavailable' using errcode='P0002';end if;
 perform 1 from public.user_organizations where organization_id=p_org and user_id=conn.user_id and revoked_at is null for update;
 if not found then raise exception 'google_owner_unavailable' using errcode='42501';end if;
 select * into conn from public.calendar_connections where organization_id=p_org and id=p_connection;
 if conn.status<>'healthy' then raise exception 'google_connection_unavailable' using errcode='42501';end if;
 if conn.calendar_selection_revision::text is distinct from p_revision then raise exception 'google_selection_stale' using errcode='40001';end if;
 fresh:=(select count(*) from public.calendar_connections where organization_id=p_org and user_id=conn.user_id and provider='google_calendar')=1 and conn.calendar_selection_revision=0 and not exists(select 1 from public.calendar_connection_calendars k join public.calendar_connections x on x.organization_id=k.organization_id and x.id=k.connection_id where k.organization_id=p_org and x.user_id=conn.user_id and k.is_destination);
 for it in select value from jsonb_array_elements(p_items) loop
  insert into public.calendar_connection_calendars(organization_id,connection_id,external_calendar_id,name,time_zone,is_primary,access_role,available,catalog_checked_at,counts_for_conflicts,is_destination,allowed_conference_types)
   values(p_org,p_connection,it->>'id',coalesce(it->>'summaryOverride',it->>'summary',it->>'id'),it->>'timeZone',coalesce((it->>'primary')::boolean,false),it->>'accessRole',not coalesce((it->>'deleted')::boolean,false),now(),
    fresh and coalesce((it->>'primary')::boolean,false),false,case when jsonb_typeof(it->'conferenceProperties'->'allowedConferenceSolutionTypes')='array' then array(select jsonb_array_elements_text(it->'conferenceProperties'->'allowedConferenceSolutionTypes')) else null end)
   on conflict(organization_id,connection_id,external_calendar_id) do update set name=excluded.name,time_zone=excluded.time_zone,is_primary=excluded.is_primary,
    allowed_conference_types=excluded.allowed_conference_types,access_role=excluded.access_role,available=excluded.available,catalog_checked_at=excluded.catalog_checked_at,sync_next_attempt_at=now();
 end loop;
 update public.calendar_connection_calendars set available=false,catalog_checked_at=now() where organization_id=p_org and connection_id=p_connection
  and not exists(select 1 from jsonb_array_elements(p_items) v where v->>'id'=external_calendar_id);
 if fresh then
  update public.calendar_connection_calendars set is_destination=true where organization_id=p_org and connection_id=p_connection and is_primary and available and access_role in ('owner','writer');
 end if;
 update public.calendar_connections set calendar_selection_revision=calendar_selection_revision+1 where organization_id=p_org and id=p_connection;
end;$$;


--
-- Name: fn_google_counts_for_conflicts(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_counts_for_conflicts(p_org uuid, p_connection uuid, p_calendar text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 -- ?????? FALHA ABERTO na AUS??NCIA de cat??logo, e a dire????o ?? deliberada.
 -- A forma `exists(... and counts_for_conflicts)` exigia linha em
 -- calendar_connection_calendars para o evento contar. Antes desta migration os
 -- tr??s leitores (grade, semente da p??gina e o motor de hor??rios livres) liam
 -- `calendar_external_events` DIRETO: toda ocupa????o contava. Numa conex??o cujo
 -- cat??logo ainda n??o foi montado ??? ou cujo calend??rio saiu do cat??logo com os
 -- eventos ainda gravados ??? a ocupa????o sumia da grade E deixava de bloquear o
 -- hor??rio. O erro barato ?? mostrar "Ocupado" a mais; o caro ?? marcar por cima
 -- de uma consulta que existe. A negativa s?? vale quando algu??m a declarou.
 select (auth.uid() is null or p_org in (select public.fn_user_org_ids())) and not exists(
  select 1 from public.calendar_connection_calendars where organization_id=p_org and connection_id=p_connection and external_calendar_id=p_calendar and not counts_for_conflicts);
$$;


--
-- Name: fn_google_coverage(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_coverage(p_org uuid, p_owner uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 select case when auth.uid() is not null and p_org not in(select public.fn_user_org_ids()) then true else exists(
  select 1 from public.calendar_connection_calendars k join public.calendar_connections c on c.organization_id=k.organization_id and c.id=k.connection_id
  where k.organization_id=p_org and c.user_id=p_owner and k.counts_for_conflicts and (
   not k.available or c.status<>'healthy' or k.access_role not in ('owner','writer','reader','writerWithoutPrivateAccess') or k.sync_coverage is null or k.sync_error is not null or k.last_sync_at is null or k.last_sync_at<now()-interval '30 minutes'
   or (k.sync_coverage->>'window_start')::timestamptz>p_start or (k.sync_coverage->>'window_end')::timestamptz<p_end)) end;
$$;


--
-- Name: fn_google_projection_stamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_projection_stamp() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare changed boolean; inbound boolean; decision boolean; redacted boolean;
begin
 redacted:=new.contact_id is not null and exists(select 1 from public.contacts where organization_id=new.organization_id and id=new.contact_id and is_anonymized);
 if redacted then
  new.google_base_projection:=null;new.google_conflict:=null;new.google_pending_write:=null;new.google_claim_token:=null;new.google_claim_until:=null;new.google_etag:=null;new.guest_email:=null;
  if tg_op='UPDATE' then new.google_claim_epoch:=old.google_claim_epoch+1;new.google_local_revision:=old.google_local_revision;new.google_synced_local_revision:=old.google_local_revision;end if;
  return new;
 end if;
 if tg_op='INSERT' then
  new.google_local_revision:=1;new.google_synced_local_revision:=0;
  if auth.uid() is not null then
   new.google_base_projection:=null;new.google_etag:=null;new.google_pending_write:=null;new.google_conflict:=null;
   new.google_claim_token:=null;new.google_claim_epoch:=0;new.google_claim_until:=null;
   new.google_connection_id:=null;new.google_calendar_id:=null;new.google_event_id:=null;
  end if;
  return new;
 end if;
 decision:=auth.uid()=old.owner_user_id and public.fn_role_at_least(new.organization_id,'agent') and public.fn_support_write_allowed(new.organization_id)
  and old.google_conflict is not null and new.google_conflict-'resolution'=old.google_conflict-'resolution'
  and new.google_conflict->'resolution'->>'actor_id'=auth.uid()::text
  and new.google_conflict->'resolution'->>'choice' in ('google','local','preserve_remote')
  and old.google_conflict->>'revision'=old.revision::text and old.google_conflict->>'local_revision'=old.google_local_revision::text
  and old.google_conflict->>'etag' is not distinct from old.google_etag;
 if auth.uid() is not null and (row(new.google_synced_at,new.google_sync_error) is distinct from row(old.google_synced_at,old.google_sync_error)
  or (new.google_next_attempt_at is distinct from old.google_next_attempt_at and not coalesce(auth.uid()=old.owner_user_id and public.fn_role_at_least(new.organization_id,'agent') and public.fn_support_write_allowed(new.organization_id)
    and new.google_next_attempt_at<=clock_timestamp() and (old.google_conflict is null or decision),false))) then
  raise exception 'google_metadata_private' using errcode='42501';end if;
 if auth.uid() is not null and ((new.google_conflict is distinct from old.google_conflict and not coalesce(decision,false)) or row(new.google_base_projection,new.google_pending_write,new.google_claim_token,new.google_claim_epoch,new.google_claim_until,new.google_synced_local_revision,new.google_etag,new.google_connection_id,new.google_calendar_id,new.google_event_id)
  is distinct from row(old.google_base_projection,old.google_pending_write,old.google_claim_token,old.google_claim_epoch,old.google_claim_until,old.google_synced_local_revision,old.google_etag,old.google_connection_id,old.google_calendar_id,old.google_event_id)) then
  raise exception 'google_metadata_private' using errcode='42501';
 end if;
 changed:=row(new.starts_at,new.ends_at,new.time_zone,new.status='cancelled',new.title,new.description,new.location_kind,new.location_details,new.guest_email)
  is distinct from row(old.starts_at,old.ends_at,old.time_zone,old.status='cancelled',old.title,old.description,old.location_kind,old.location_details,old.guest_email);
 -- ??nica entrada que modifica base e dom??nio juntos ?? o n??cleo service-only.
 -- N??o h?? GUC ou flag no body p??blico que suprima revis??o.
 inbound:=row(new.title,new.description,new.location_kind,new.location_details,new.guest_email) is not distinct from row(old.title,old.description,old.location_kind,old.location_details,old.guest_email) and auth.uid() is null and new.google_base_projection is distinct from old.google_base_projection
  and (new.google_base_projection->'shared'->>'starts_at')::timestamptz=new.starts_at
  and (new.google_base_projection->'shared'->>'ends_at')::timestamptz=new.ends_at
  and new.google_base_projection->'shared'->>'time_zone'=new.time_zone
  and (new.google_base_projection->'shared'->>'cancelled')::boolean=(new.status='cancelled');
 new.google_local_revision:=old.google_local_revision+case when changed and not coalesce(inbound,false) then 1 else 0 end;
 if changed then new.google_next_attempt_at:=now(); end if;
 return new;
end;$$;


--
-- Name: fn_google_redact_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_redact_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 if new.is_anonymized then
  update public.calendar_appointments set google_base_projection=null,google_conflict=null,google_pending_write=null,
   google_claim_epoch=google_claim_epoch+1,google_claim_token=null,google_claim_until=null,google_etag=null,
   google_sync_error='Contato anonimizado. Sincroniza????o interrompida.',guest_email=null
   where organization_id=new.organization_id and contact_id=new.id;
 end if;return new;
end;$$;


--
-- Name: fn_google_resolve(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_resolve(p_org uuid, p_id uuid, p_revision text, p_local_revision text, p_etag text, p_choice text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.calendar_appointments; contact uuid;
begin
 if auth.uid() is null or not public.fn_role_at_least(p_org,'agent') or not public.fn_support_write_allowed(p_org) then raise exception 'google_resolution_forbidden' using errcode='42501';end if;
 if not public.fn_session_mfa_proven() then raise exception 'google_mfa_required' using errcode='42501';end if;
 select contact_id into contact from public.calendar_appointments where organization_id=p_org and id=p_id;
 if contact is not null then perform public.fn_service_lock(p_org,contact);end if;
 select * into a from public.calendar_appointments where organization_id=p_org and id=p_id for update;
 if not found or a.owner_user_id is distinct from auth.uid() then raise exception 'google_resolution_forbidden' using errcode='42501';end if;
 if a.revision::text is distinct from p_revision or a.google_local_revision::text is distinct from p_local_revision
  or a.google_etag is distinct from p_etag then raise exception 'google_stale' using errcode='40001';end if;
 if p_choice='retry' then
  if a.google_conflict is not null then raise exception 'google_conflict_requires_choice' using errcode='40001';end if;
  update public.calendar_appointments set google_next_attempt_at=now() where organization_id=p_org and id=p_id;
 else
  if p_choice not in ('google','local','preserve_remote') or a.google_conflict is null then raise exception 'google_choice_invalid' using errcode='22023';end if;
  -- O trigger reconhece somente esta forma autenticada: o corpo da compara????o
  -- e as revis??es n??o mudam, actor_id ?? auth.uid(), n??o input do browser.
  update public.calendar_appointments set google_conflict=google_conflict||jsonb_build_object('resolution',jsonb_build_object('choice',p_choice,'actor_id',auth.uid())),google_next_attempt_at=now()
   where organization_id=p_org and id=p_id;
 end if;
end;$$;


--
-- Name: fn_google_selection(uuid, jsonb, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_google_selection(p_org uuid, p_revisions jsonb, p_sources uuid[], p_destination uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor uuid:=auth.uid(); expected jsonb; actual jsonb;
begin
 if actor is null or not public.fn_role_at_least(p_org,'agent') or not public.fn_support_write_allowed(p_org) then raise exception 'google_selection_forbidden' using errcode='42501';end if;
 if not public.fn_session_mfa_proven() then raise exception 'google_mfa_required' using errcode='42501';end if;
 perform 1 from public.user_organizations where organization_id=p_org and user_id=actor and revoked_at is null for update;
 if not found then raise exception 'google_owner_unavailable' using errcode='42501';end if;
 select jsonb_agg(value order by value->>'connection_id') into expected from jsonb_array_elements(p_revisions);
 select jsonb_agg(jsonb_build_object('connection_id',id,'revision',calendar_selection_revision::text) order by id::text) into actual from public.calendar_connections where organization_id=p_org and user_id=actor and provider='google_calendar';
 if actual is distinct from expected then raise exception 'google_selection_stale' using errcode='40001';end if;
 if not exists(select 1 from public.calendar_connection_calendars k join public.calendar_connections c on c.id=k.connection_id and c.organization_id=k.organization_id
  where k.organization_id=p_org and k.id=p_destination and c.user_id=actor and c.status='healthy' and k.available and k.access_role in ('owner','writer')) then raise exception 'google_destination_unavailable' using errcode='42501';end if;
 if exists(select 1 from unnest(p_sources) selected(id) where not exists(select 1 from public.calendar_connection_calendars k join public.calendar_connections c on c.id=k.connection_id and c.organization_id=k.organization_id
  where k.organization_id=p_org and k.id=selected.id and c.user_id=actor and c.status='healthy' and k.available and k.access_role in ('owner','writer','reader','writerWithoutPrivateAccess'))) then raise exception 'google_source_unavailable' using errcode='42501';end if;
 update public.calendar_connection_calendars k set is_destination=false from public.calendar_connections c where k.organization_id=p_org and c.organization_id=p_org and k.connection_id=c.id and c.user_id=actor;
 update public.calendar_connection_calendars k set is_destination=k.id=p_destination,counts_for_conflicts=k.id=any(p_sources),sync_next_attempt_at=now() from public.calendar_connections c where k.organization_id=p_org and c.organization_id=p_org and k.connection_id=c.id and c.user_id=actor;
 update public.calendar_connections set calendar_selection_revision=calendar_selection_revision+1 where organization_id=p_org and user_id=actor and provider='google_calendar';
end;$$;


--
-- Name: fn_is_platform_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_is_platform_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.platform_admins
    where user_id = auth.uid() and revoked_at is null
  );
$$;


--
-- Name: fn_job_service_boundary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_job_service_boundary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b jsonb;
begin
 if new.kind not in ('inbound_turn','followup_turn','case_reply_turn','operator_turn') then return new; end if;
 if new.payload ? 'inbound_message_id' then
   select jsonb_build_object('organization_id',m.organization_id,'contact_id',m.contact_id,
    'conversation_id',m.conversation_id,'service_revision',m.service_revision,
    'demanda_id',m.demanda_id,'demanda_revision',m.demanda_revision) into b
    from public.messages m where m.id::text=new.payload->>'inbound_message_id'
     and m.organization_id=new.organization_id and m.contact_id=new.contact_id and m.service_revision is not null;
 elsif new.payload ? 'origin_job_id' then
   select j.payload->'service_boundary' into b from public.job_queue j
    where j.id::text=new.payload->>'origin_job_id' and j.organization_id=new.organization_id and j.contact_id=new.contact_id;
 elsif new.payload ? 'case_id' then
   select ac.context_snapshot->'service_boundary' into b from public.agent_cases ac
    join public.conversations c on c.id=ac.conversation_id and c.organization_id=ac.organization_id
    where ac.id::text=new.payload->>'case_id' and ac.organization_id=new.organization_id and c.contact_id=new.contact_id;
 else b:=new.payload->'service_boundary'; end if;
 new.payload := (new.payload - 'service_boundary') || jsonb_build_object('service_boundary',b);
 return new;
end; $$;


--
-- Name: fn_lancamento_pago_e_imutavel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_lancamento_pago_e_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.paid_at is not null and (
       new.amount_cents is distinct from old.amount_cents
    or new.account_id   is distinct from old.account_id
    or new.direction    is distinct from old.direction
    or new.entry_date   is distinct from old.entry_date
  ) then
    -- N??o ?? capricho: um lan??amento pago j?? foi conciliado com extrato. Mud??-lo
    -- faz o relat??rio de ontem contar outra hist??ria hoje, sem deixar rastro.
    -- O caminho certo ?? o contra-lan??amento.
    raise exception 'lancamento_pago_imutavel'
      using errcode = '42501',
            hint = 'Um lan??amento j?? pago n??o muda de valor, conta, dire????o ou data. Estorne com um contra-lan??amento.';
  end if;
  return new;
end $$;


--
-- Name: fn_lgpd_anonymize_contact(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_lgpd_anonymize_contact(p_organization_id uuid, p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c public.contacts; support jsonb;
begin
 support:=public.fn_support_context();
 if auth.uid() is null or not public.fn_support_write_allowed(p_organization_id)
  or not (public.fn_role_at_least(p_organization_id,'admin') or (public.fn_is_platform_admin() and support is null)) then
  raise exception 'contact_anonymize_forbidden' using errcode='42501';
 end if;
 if not public.fn_session_mfa_proven() then raise exception 'contact_anonymize_mfa_required' using errcode='42501';end if;
 perform public.fn_service_lock(p_organization_id,p_contact_id);
 select * into c from public.contacts where organization_id=p_organization_id and id=p_contact_id for update;
 if not found then raise exception 'contact_not_found' using errcode='P0002';end if;
 if c.is_anonymized then return jsonb_build_object('already_anonymized',true,'anonymized_at',c.anonymized_at);end if;
 update public.contacts set name=null,display_name='Contato Anonimizado #'||substring(p_contact_id::text from 1 for 8),
  email=null,phone_number=null,cpf_encrypted=null,cpf_hash=null,birthdate=null,
  is_anonymized=true,anonymized_at=now(),updated_at=now()
  where organization_id=p_organization_id and id=p_contact_id returning * into c;
 return jsonb_build_object('already_anonymized',false,'anonymized_at',c.anonymized_at);
end;$$;


--
-- Name: fn_lgpd_cascade_redact_contact(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_lgpd_cascade_redact_contact(p_organization_id uuid, p_contact_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_already bool;
  v_counts jsonb := '{}'::jsonb;
  v_media_paths text[] := '{}';
  v_anon_label text;
  v_count int;
  -- As grafias do telefone desta pessoa, capturadas ANTES de o passo 1 zerar
  -- `contacts.phone_number`. A ordem aqui n??o ?? detalhe: o expurgo da
  -- prospec????o roda ~150 linhas depois do `update contacts`, e ler o telefone
  -- l?? embaixo leria NULL ??? o bra??o por telefone existiria no c??digo e n??o
  -- alcan??aria linha nenhuma, que ?? pior que n??o existir, porque parece feito.
  v_variantes text[] := '{}';
begin
  perform public.fn_service_lock(p_organization_id,p_contact_id);
  select is_anonymized into v_already
    from contacts
    where id = p_contact_id and organization_id = p_organization_id;

  if not found then
    raise exception 'contact not found' using errcode = 'P0002';
  end if;

  if v_already then
    return jsonb_build_object('already_anonymized', true, 'counts', v_counts, 'media_paths', v_media_paths);
  end if;

  v_anon_label := 'Cliente Anonimizado #' || substring(p_contact_id::text from 1 for 8);

  -- Capturado AGORA, enquanto o telefone ainda existe (o passo 1 o apaga).
  select coalesce(public.fn_telefone_variantes(phone_number), '{}')
    into v_variantes
    from contacts
    where id = p_contact_id and organization_id = p_organization_id;

  -- Collect media storage paths (we only delete what we own ??? media_storage_path)
  select coalesce(array_agg(distinct media_storage_path) filter (where media_storage_path is not null), '{}')
    into v_media_paths
    from messages
    where organization_id = p_organization_id
      and conversation_id in (
        select id from conversations
          where contact_id = p_contact_id and organization_id = p_organization_id
      );

  -- 1. contacts (irreversible)
  update contacts set
    name = v_anon_label,
    display_name = v_anon_label,
    email = null,
    -- email_normalized N??O entra: ?? GENERATED ALWAYS AS (lower(trim(email)))
    -- e o Postgres recusa escrita nela ??? a linha acima j?? a zera por deriva????o.
    -- Com a atribui????o, o cascade INTEIRO abortava e nada era anonimizado.
    phone_number = null,
    cpf_encrypted = null,
    cpf_hash = null,
    birthdate = null,
    is_anonymized = true,
    anonymized_at = now(),
    consent = '{}'::jsonb,
    source_metadata = '{}'::jsonb,
    tags = '{}'::text[],
    updated_at = now()
  where id = p_contact_id and organization_id = p_organization_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('contacts', v_count);

  -- 2. conversations metadata + preview strip
  update conversations set
    metadata = '{}'::jsonb,
    last_message_preview = null,
    -- O motivo CRU da ??ltima passagem (migration 0291). ?? c??digo de
    -- vocabul??rio, n??o texto livre ??? mas ele diz que ESTA pessoa foi escalada
    -- por irrita????o, por assunto jur??dico ou por suspeita de opt-out, e isso ??
    -- um fato sobre ela. Entra NESTE update, e n??o num segundo: mesmo
    -- predicado, mesmas linhas, metade das varreduras.
    --
    -- ?????? `last_handoff_reason` ?? CHAVE DE NEG??CIO em outro m??dulo: a ponte de
    -- voz limpa o sil??ncio filtrando pelo VALOR da coluna
    -- (`lib/wacalls/events-bridge.ts`). Zer??-la num contato anonimizado ??
    -- seguro ??? n??o h?? chamada viva de contato anonimizado ??? e ?? a raz??o de
    -- esta entrega N??O usar essa coluna para texto rico: ela continua
    -- recebendo s?? o c??digo, e o texto vive em `passagens_de_atendimento`.
    last_handoff_reason = null,
    updated_at = now()
  where contact_id = p_contact_id and organization_id = p_organization_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('conversations', v_count);

  -- 3. messages: redact body + null media + strip metadata (preserve status/timestamps/conversation_id)
  update messages set
    body = '[mensagem anonimizada]',
    media_url = null,
    media_mime = null,
    media_size_bytes = null,
    media_storage_path = null,
    metadata = '{}'::jsonb,
    updated_at = now()
  where organization_id = p_organization_id
    and conversation_id in (
      select id from conversations
        where contact_id = p_contact_id and organization_id = p_organization_id
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('messages', v_count);

  -- 4. crm_lead_activities ??? strip payload, metadata E reason (migration 0071).
  --    `reason` ?? texto livre escrito por LLM sobre a conversa do lead: supor que
  --    nunca conter?? um nome ?? a suposi????o que falha. `evidence` N??O ?? limpa ???
  --    guarda s?? ids, e as linhas apontadas s??o redigidas por conta pr??pria.
  update crm_lead_activities set
    payload = '{}'::jsonb,
    metadata = '{}'::jsonb,
    reason = null
  where organization_id = p_organization_id
    and (
      contact_id = p_contact_id
      or lead_id in (
        select lead_id from crm_lead_links
          where target_kind = 'contact'
            and target_id = p_contact_id
            and organization_id = p_organization_id
      )
      or lead_id in (
        select id from crm_leads
          where contact_id = p_contact_id and organization_id = p_organization_id
      )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('activities', v_count);

  -- 5. crm_leads ??? strip title/description/custom_fields/source_metadata/tags but PRESERVE pipeline/stage/value
  update crm_leads set
    title = v_anon_label,
    description = null,
    custom_fields = '{}'::jsonb,
    source_metadata = '{}'::jsonb,
    tags = '{}'::text[],
    updated_at = now()
  where organization_id = p_organization_id
    and (
      contact_id = p_contact_id
      or id in (
        select lead_id from crm_lead_links
          where target_kind = 'contact'
            and target_id = p_contact_id
            and organization_id = p_organization_id
      )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('leads', v_count);

  -- 6. orders ??? PRESERVE values + status + timestamps. Strip personal fields from payload jsonb
  --    and replace customer_external_id with null (FK-safe; soft de-link). Keep contact_id null.
  update orders set
    payload = (coalesce(payload, '{}'::jsonb))
      - 'customer'
      - 'customer_name'
      - 'customer_email'
      - 'customer_phone'
      - 'shipping_address'
      - 'billing_address'
      - 'contact_identification',
    customer_external_id = null,
    contact_id = null,
    is_anonymized = true,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('orders', v_count);
  -- REAPLICADO AO DERIVAR ESTE AP??NDICE (merge da main, 0359 comanda).
  -- O Postgres troca o corpo INTEIRO num `create or replace`: um ap??ndice
  -- escrito sobre uma vers??o anterior da fun????o APAGA, em sil??ncio, o passo
  -- que outra entrega acrescentou. Anonimizar devolveria SUCESSO com o texto
  -- da comanda ainda leg??vel ??? e o SLA marcado como cumprido.
  -- 6b. sales ??? a comanda. PRESERVA valor, status e datas, e N??O desliga o
  --     contato: a venda ?? registro financeiro (e fiscal) da organiza????o, e
  --     deslig??-la do contato faria o relat??rio por cliente deixar de fechar
  --     com o faturamento do per??odo ??? diverg??ncia muda, meses depois, num
  --     n??mero que ningu??m consegue reconciliar. O contato apontado j?? ??
  --     `Cliente Anonimizado #N`; o que sai daqui ?? o TEXTO LIVRE, que ?? onde
  --     a pessoa ?? nomeada de novo ("cliente da Ana, filha da Dona Maria").
  --     Os itens (`sale_items`) n??o entram: `description` ali ?? o nome do
  --     SERVI??O, congelado na inclus??o, e apag??-lo destruiria o relat??rio por
  --     servi??o sem tirar dado de pessoa nenhum.
  update sales set
    notes = null,
    cancel_reason = case when cancel_reason is null then null else '[redigido]' end,
    reverse_reason = case when reverse_reason is null then null else '[redigido]' end,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('sales', v_count);

  -- 7. enqueue media for async deletion (idempotent via unique (bucket, object_path))
  if array_length(v_media_paths, 1) > 0 then
    insert into storage_redaction_queue (organization_id, request_id, bucket, object_path)
    select p_organization_id, p_request_id, 'whatsapp-media', path
      from unnest(v_media_paths) as path
      where path is not null and length(path) > 0
    on conflict (bucket, object_path) do nothing;
  end if;

  -- 7b. voice_calls ??? o TELEFONE de quem falou ao telefone (migration 0235).
  --
  -- `peer_phone` ?? `not null` e guarda o n??mero da outra ponta: depois de
  -- anonimizar o contato, ele sobrevivia ligado ao `contact_id` e reidentificava
  -- a pessoa que pediu para ser esquecida. ?? o mesmo argumento que a foto de
  -- perfil j?? tinha (ver o bloco do avatar em `lib/lgpd/redact-cascade.ts`):
  -- anonimizar em toda parte menos numa ?? n??o ter anonimizado.
  --
  -- O que fica: dire????o, status, motivo do fim, marcas de tempo e dura????o. Um
  -- registro de "houve uma chamada de 12 minutos" sem n??mero e sem dono n??o
  -- identifica ningu??m e ?? o que sustenta a m??trica do atendente e a fatura.
  -- `peer_phone` ?? NOT NULL, ent??o recebe o r??tulo, n??o `null`.
  update voice_calls set
    peer_phone = v_anon_label,
    owner_user_id = null,
    created_by = null,
    updated_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('voice_calls', v_count);

  -- Native discovery stores commercial/person data before the Inbox exists.
  -- Keep only keyed suppression tokens, restricted to the server, to prevent
  -- another extraction from reintroducing this erased candidate.
  --
  -- O PREDICADO ALCAN??A POR V??NCULO **OU** POR TELEFONE, e o segundo bra??o ?? o
  -- que conserta um buraco real: quando o telefone raspado j?? pertencia a um
  -- contato conhecido da organiza????o, `lib/prospecting/store.ts` grava o
  -- candidato como `skipped` e DEIXA `contact_id` nulo de prop??sito (l?? o
  -- v??nculo ?? o freio de m??o do envio, em `worker.ts`). S?? pelo `contact_id`,
  -- essa pessoa ??? justamente a que a empresa j?? conhece ??? pedia exclus??o,
  -- recebia sucesso, a auditoria gravava `lgpd.redact_executed`, e o nome, o
  -- telefone e o endere??o dela seguiam leg??veis aqui.
  --
  -- Em expurgo os dois erros n??o t??m o mesmo pre??o: alcan??ar demais custa um
  -- registro de prospec????o descartado; alcan??ar de menos ?? viola????o legal. Por
  -- isso o `or`, e por isso a compara????o por VARIANTE do nono d??gito.
  update prospecting_candidates set suppression_salt = gen_random_bytes(32)
  where organization_id = p_organization_id
    and (contact_id = p_contact_id
         or (phone is not null
             and regexp_replace(phone, '\D', '', 'g') = any (v_variantes)))
    and suppression_salt is null;
  update prospecting_candidates set
    suppression_place = hmac(convert_to(place_id, 'UTF8'), suppression_salt, 'sha256'),
    suppression_phone = case when phone is null then null
      else hmac(convert_to(phone, 'UTF8'), suppression_salt, 'sha256') end,
    place_id = 'redacted:' || id::text,
    phone = null,
    data = jsonb_build_object('key', 'redacted:' || id::text,
      'name', v_anon_label, 'phone', null, 'website', null,
      'category', null, 'address', null, 'maps_url', null,
      'rating', null, 'reviews', null, 'emails', '[]'::jsonb, 'socials', '[]'::jsonb),
    status = 'skipped', service_boundary = null, error = null, updated_at = now()
  -- MESMO predicado do bloco anterior. Se os dois divergirem, a linha alcan??ada
  -- por um e n??o pelo outro fica com `suppression_salt` semeado e os dados
  -- pessoais intactos ??? um estado que parece tratado e n??o est??.
  where organization_id = p_organization_id
    and (contact_id = p_contact_id
         or (phone is not null
             and regexp_replace(phone, '\D', '', 'g') = any (v_variantes)));
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('prospecting_candidates', v_count);


  -- agent_cases ??? o que a IA escreveu SOBRE a pessoa quando travou (migration 0280).
  --
  -- O caso ?? o texto que a equipe l?? antes de decidir: `title`, `summary` e
  -- `blocker` saem do modelo a partir da conversa, e `context_snapshot` ?? o
  -- recorte dessa conversa que o motor mandou para ele. Nada disso ?? registro de
  -- opera????o ??? ?? o relato do problema de uma pessoa identific??vel, escrito por
  -- m??quina. Sem este passo, anonimizar devolvia SUCESSO com o relato intacto.
  --
  -- As tr??s colunas de texto s??o `not null`: recebem r??tulo e texto fixo, nunca
  -- `null` (a mesma raz??o de `voice_calls.peer_phone` logo acima).
  --
  -- ?????? `updated_at` FICA FORA DO `set`, de prop??sito. O cobrador de caso parado
  -- (`app/api/v1/cron/case-stale-watcher/route.ts`) l?? `updated_at` como "algu??m
  -- da equipe encostou neste caso". A cascata n??o ?? algu??m encostando: escrever
  -- ali faria a anonimiza????o ADIAR a cobran??a de um caso que continua parado, e
  -- o efeito s?? apareceria como um cliente esperando mais tempo.
  --
  -- O v??nculo ?? pela CONVERSA porque `agent_cases` n??o tem FK para `contacts`.
  update agent_cases set
    title = v_anon_label,
    summary = '[resumo anonimizado]',
    blocker = '[bloqueio anonimizado]',
    context_snapshot = '{}'::jsonb
  where organization_id = p_organization_id
    and conversation_id in (
      select id from conversations
        where contact_id = p_contact_id and organization_id = p_organization_id
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_cases', v_count);

  -- agent_case_events ??? a linha do tempo do caso (migration 0280).
  --
  -- `body` ?? o que a pessoa da equipe escreveu ao responder o caso e o que o
  -- agente registrou sobre o que o LEAD respondeu; `metadata` carrega o recorte
  -- que o motor anexou. `kind`, `actor_kind`, `human_action` e `created_at`
  -- FICAM: s??o o registro de que houve um toque humano e quando ??? opera????o, n??o
  -- dado da pessoa, e ?? deles que sai a m??trica de atendimento.
  update agent_case_events set
    body = null,
    metadata = '{}'::jsonb
  where organization_id = p_organization_id
    and case_id in (
      select id from agent_cases
        where organization_id = p_organization_id
          and conversation_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_case_events', v_count);

  -- demandas ??? o assunto do pedido (migration 0280).
  --
  -- `assunto` ?? texto livre sobre o que a pessoa pediu. O resto da linha ?? a
  -- opera????o da demanda (origem, estado, dono, prazo, desfecho) e fica de p??:
  -- apagar a linha inteira tiraria da organiza????o a resposta a "quantos pedidos
  -- houve em mar??o", que ?? o mesmo argumento do compromisso da agenda.
  --
  -- FK direta (`demandas.contact_id` ?? `not null`), ent??o o v??nculo ?? o contato.
  update demandas set
    assunto = null
  where organization_id = p_organization_id
    and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('demandas', v_count);

  -- agent_inbox_items ??? o aviso que leva o texto do caso para a Central (migration 0280).
  --
  -- O `body` do aviso de caso parado EMBUTE o t??tulo do caso
  -- (`app/api/v1/cron/case-stale-watcher/route.ts:128`), e o do handoff embute o
  -- motivo da parada (`lib/ai/handoff/orchestrator.ts:335`). Redigir o caso e
  -- deixar o aviso de p?? seria anonimizar em toda parte menos numa ??? que ?? n??o
  -- ter anonimizado. O molde (resolver + trocar o corpo + soltar a refer??ncia) ??
  -- o de `fn_meet_redact_contact`, que j?? faz isto para o aviso de compromisso.
  --
  -- ?????? O V??NCULO ?? POLIM??RFICO E TEM TR??S BRA??OS, n??o dois. Medido nos
  -- produtores, n??o suposto: `handoff` nasce com `ref_kind='contact'`
  -- (`lib/ai/handoff/orchestrator.ts:339`) E com `ref_kind='conversation'`
  -- (`lib/agent-engine/agent/inbound-turn.ts:4100`); `case_stale` nasce SEMPRE
  -- com `ref_kind='agent_case'` (a rota do cron acima, e a pol??tica em
  -- `lib/ai/inbox-destino.ts:38`). Um predicado com s?? os dois primeiros bra??os
  -- casa ZERO avisos de caso parado ??? e casar zero linha n??o ?? erro: ?? sucesso
  -- com o texto intacto.
  --
  -- Os `kind` s??o os MEDIDOS no CHECK vigente (`supabase/baseline.sql`, bloco
  -- ??nico de `agent_inbox_items_kind_check`). `case_opened` N??O existe, e kind
  -- inexistente num `in (...)` tamb??m casa zero e devolve sucesso. Para
  -- reconferir sem acreditar nesta prosa:
  --   grep -n "agent_inbox_items_kind_check check" -A40 supabase/baseline.sql
  update agent_inbox_items set
    status = 'resolved',
    resolved_at = now(),
    body = 'Contato anonimizado.',
    ref_id = null
  where organization_id = p_organization_id
    -- `aviso_de_caso_nao_entregue` (migration 0292) entra AQUI e n??o num
    -- passo pr??prio: ?? o mesmo predicado polim??rfico, e o bra??o
    -- `ref_kind='agent_case'` j?? alcan??a o caso do titular. O corpo do aviso
    -- embute o t??tulo do caso, que ?? texto sobre a pessoa.
    and kind in ('handoff', 'case_stale', 'aviso_de_caso_nao_entregue')
    and (
      (ref_kind = 'contact' and ref_id = p_contact_id)
      or (ref_kind = 'conversation' and ref_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          ))
      or (ref_kind = 'agent_case' and ref_id in (
            select id from agent_cases
              where organization_id = p_organization_id
                and conversation_id in (
                  select id from conversations
                    where contact_id = p_contact_id and organization_id = p_organization_id
                )
          ))
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_inbox_items', v_count);

  -- agent_case_chat_messages ??? a consulta interna da equipe ?? IA SOBRE o caso
  -- (migration 0281). FK DIRETA para `contacts`, ent??o o v??nculo ?? o titular e
  -- n??o precisa passar pela conversa.
  --
  -- `redacted_at is null` no `where` ?? o que torna o passo IDEMPOTENTE: a
  -- varredura di??ria de reda????es incompletas roda a fun????o de novo, e sem essa
  -- condi????o o carimbo de QUANDO se apagou seria reescrito a cada rodada.
  --
  -- A linha N??O ?? apagada, s?? o texto: quem abrir o caso depois continua vendo
  -- que a equipe perguntou N vezes, quando, e se a IA respondeu. Apagar a linha
  -- inteira ficaria verde num teste de "o texto sumiu" e tiraria da organiza????o
  -- a resposta a "quanto a equipe deliberou sobre este caso".
  update agent_case_chat_messages set
    body = null,
    redacted_at = now()
  where organization_id = p_organization_id
    and contact_id = p_contact_id
    and redacted_at is null;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('agent_case_chat_messages', v_count);

  -- passagens_de_atendimento ??? o BRIEFING ?? sobre a pessoa (migration 0291).
  --
  -- A linha guarda o que a IA concluiu sobre um atendimento de algu??m
  -- identific??vel: o que ela entendeu que a pessoa quer (`title`), a narrativa
  -- que quem assumiu leu (`body`), as PALAVRAS LITERAIS do cliente (`notes`), o
  -- texto livre de quem passou (`content`) e o que a IA j?? tinha tentado
  -- (`tentativas`). Nada disso ?? registro de opera????o ??? ?? o relato do problema
  -- de uma pessoa, escrito por m??quina, na tela de quem vai responder.
  --
  -- `body` ?? `not null` e recebe o R??TULO, n??o `null` ??? a mesma raz??o de
  -- `voice_calls.peer_phone` e de `agent_cases.title` acima: coluna obrigat??ria
  -- anulada aborta o cascade INTEIRO, e um cascade abortado n??o anonimiza nada.
  --
  -- O que FICA, de prop??sito: `motor`, `origem`, `motivo_codigo`,
  -- `cliente_avisado`, `aviso_motivo_codigo`, `criado_em` e o par de
  -- reconhecimento. S??o opera????o ??? quantas passagens houve, por qu??, quanto
  -- tempo at?? algu??m assumir. Um passo que apagasse a linha inteira ficaria
  -- verde num teste de "o texto sumiu" e tiraria da organiza????o a resposta a
  -- "quantos atendimentos a IA devolveu em mar??o, e quanto tempo esperaram".
  --
  -- O v??nculo ?? a FK DIRETA `contact_id`: a tabela a carrega exatamente para
  -- este passo n??o precisar passar pela conversa.
  update passagens_de_atendimento set
    body       = v_anon_label,
    title      = null,
    notes      = null,
    content    = null,
    tentativas = '[]'::jsonb
  where organization_id = p_organization_id and contact_id = p_contact_id;
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('passagens_de_atendimento', v_count);

  -- entregas_de_aviso_de_caso ??? o registro do aviso ao suporte (migration 0292).
  --
  -- A tabela N??O guarda o texto do aviso (s?? `corpo_hash`), e a ??nica coluna
  -- capaz de ecoar um dado da pessoa ?? `erro_detalhe`: ali vai o texto CRU que
  -- o transporte devolveu, truncado, e um provedor que recusa um envio costuma
  -- devolver o destinat??rio dentro da mensagem de erro.
  --
  -- O que FICA, de prop??sito: `status`, `erro_codigo`, `tentativas`,
  -- `enviado_em`, `destino`, `corpo_hash`. S??o opera????o ??? quantos avisos sa??ram,
  -- quantos falharam e por qu??. Um passo que apagasse a linha inteira ficaria
  -- verde num teste de "o texto sumiu" e tiraria da organiza????o a resposta a
  -- "quantos avisos n??o chegaram em mar??o". `destino` ?? o telefone da EQUIPE,
  -- n??o do titular: anonimizar um cliente n??o apaga o n??mero do plant??o.
  --
  -- ?????? PONTO CEGO DECLARADO: `tests/invariants/lgpd-cascata-alcanca-quem-
  -- guarda-pessoa.test.ts` s?? cobra tabela com FK para `contacts` E coluna cujo
  -- NOME case o padr??o de PII. Esta tabela n??o satisfaz nenhuma das duas ??? o
  -- gate ficaria VERDE sem este passo. Ele entra porque ?? certo, n??o porque o
  -- gate cobra, e isto est?? escrito aqui para a pr??xima sess??o n??o o remover
  -- achando que ?? ornamento. Quem o vigia ?? a catraca
  -- `tests/invariants/cascata-lgpd-nao-encolhe.test.ts`.
  --
  -- O v??nculo ?? pela CONVERSA, como o de `agent_cases`: esta tabela aponta para
  -- o caso, e o caso n??o tem FK para `contacts`.
  update entregas_de_aviso_de_caso set
    erro_detalhe = null
  where organization_id = p_organization_id
    and case_id in (
      select id from agent_cases
        where organization_id = p_organization_id
          and conversation_id in (
            select id from conversations
              where contact_id = p_contact_id and organization_id = p_organization_id
          )
    );
  get diagnostics v_count = row_count;
  v_counts := v_counts || jsonb_build_object('entregas_de_aviso_de_caso', v_count);

  -- 8. dense audit row
  insert into api_audit_log (organization_id, action, actor_user_id, resource_type, resource_id, metadata, bypassed_rls)
  values (
    p_organization_id,
    'lgpd.redact_executed',
    null,
    'contact',
    p_contact_id,
    jsonb_build_object(
      'cascaded_to', v_counts,
      'media_queued', coalesce(array_length(v_media_paths, 1), 0),
      'request_id', p_request_id
    ),
    true
  );

  return jsonb_build_object(
    'already_anonymized', false,
    'counts', v_counts,
    'media_paths', v_media_paths
  );
end;
$$;


--
-- Name: fn_liberar_leads_do_agente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_liberar_leads_do_agente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- ANTES de a FK aplicar seu SET NULL. Zera os DOIS campos: deixar
  -- `owner_kind = 'ai'` com o agente nulo ?? exatamente o estado que
  -- `crm_leads_owner_kind_coherence` pro??be.
  update public.crm_leads
     set owner_agent_id = null,
         owner_kind     = null
   where owner_agent_id = old.id;
  return old;
end $$;


