--
-- Name: fn_proteger_tabelas_de_organizacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_proteger_tabelas_de_organizacao() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare r record;
begin
 for r in
   select c.relname
     from pg_class c
     join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relkind = 'r'
      and not c.relrowsecurity
      and exists (
        select 1 from pg_attribute a
         where a.attrelid = c.oid
           and a.attname = 'organization_id'
           and a.attnum > 0
           and not a.attisdropped)
    order by c.relname
 loop
   execute format('alter table public.%I enable row level security', r.relname);
   execute format('revoke all on public.%I from anon', r.relname);
   execute format('drop policy if exists tenant_isolation_%s_all on public.%I', r.relname, r.relname);
   execute format(
     'create policy tenant_isolation_%s_all on public.%I for all
        using (organization_id in (select * from public.fn_user_org_ids()))
        with check (organization_id in (select * from public.fn_user_org_ids()))',
     r.relname, r.relname);
 end loop;
end $$;


--
-- Name: fn_proximo_numero_de_comanda(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_proximo_numero_de_comanda(p_org uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- `coalesce(max)+1` sob o lock da transa????o de quem chama. Uma sequence do
  -- Postgres seria global e vazaria volume entre tenants; e o buraco de uma
  -- sequence (n??meros pulados no rollback) faria a numera????o de uma comanda
  -- parecer que houve venda cancelada onde n??o houve.
  select coalesce(max(number), 0) + 1 from public.sales where organization_id = p_org;
$$;


