-- Name: fn_publish_ai_agent_version(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_publish_ai_agent_version(p_org_id uuid, p_agent_id uuid, p_version_id uuid, p_platform_credential_verified boolean) RETURNS TABLE(agent_id uuid, version_id uuid, previous_version_id uuid, published_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 select * from public.fn_publish_ai_agent_version(p_org_id,p_agent_id,p_version_id,p_platform_credential_verified,null);
$$;


--
-- Name: fn_publish_ai_agent_version(uuid, uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_publish_ai_agent_version(p_org_id uuid, p_agent_id uuid, p_version_id uuid, p_platform_credential_verified boolean, p_expected_provenance text) RETURNS TABLE(agent_id uuid, version_id uuid, previous_version_id uuid, published_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_agent record;
  v_version record;
  v_credential record;
  v_session record;
  v_model_count integer;
  v_previous_version_id uuid;
  v_published_at timestamptz := now();
begin
  select a.id, a.organization_id, a.published_version_id, a.archived_at
    into v_agent
  from public.ai_agents a
  where a.id = p_agent_id
  for update;

  if not found then
    raise exception 'agent_not_found' using errcode = 'P0001';
  end if;
  if v_agent.organization_id <> p_org_id then
    raise exception 'agent_not_found' using errcode = 'P0001';
  end if;
  if v_agent.archived_at is not null then
    raise exception 'agent_archived' using errcode = 'P0001';
  end if;

  select v.id, v.organization_id, v.agent_id, v.status, v.provider, v.model,
         v.credential_id, v.channel_session_id, v.provisioning_origin
    into v_version
  from public.ai_agent_versions v
  where v.id = p_version_id
  for update;

  if not found then
    raise exception 'version_not_found' using errcode = 'P0001';
  end if;
  if v_version.agent_id <> p_agent_id or v_version.organization_id <> p_org_id then
    raise exception 'version_not_found' using errcode = 'P0001';
  end if;
  if p_expected_provenance is not null and (
    p_expected_provenance not in('onboarding','legacy_reconciliation') or
    v_version.provisioning_origin is distinct from p_expected_provenance or
    (select count(*) from public.ai_agent_versions own_version where own_version.organization_id=p_org_id and own_version.agent_id=p_agent_id)<>1
  ) then raise exception 'existing_version_requires_review' using errcode='P0001';end if;
  if v_version.status not in ('draft', 'superseded') then
    raise exception 'version_invalid_state' using errcode = 'P0001';
  end if;

  if v_version.credential_id is null and p_platform_credential_verified is not true then
    raise exception 'credential_missing' using errcode = 'P0001';
  end if;

  if v_version.credential_id is not null then
  select c.id, c.organization_id, c.provider, c.is_active, c.validated_at
    into v_credential
  from public.ai_provider_credentials c
  where c.id = v_version.credential_id;

  if not found or v_credential.organization_id <> p_org_id then
    raise exception 'credential_not_found' using errcode = 'P0001';
  end if;
  if not v_credential.is_active then
    raise exception 'credential_inactive' using errcode = 'P0001';
  end if;
  if v_credential.validated_at is null then
    raise exception 'credential_not_validated' using errcode = 'P0001';
  end if;
  if v_credential.provider <> v_version.provider then
    raise exception 'credential_provider_mismatch' using errcode = 'P0001';
  end if;

  end if;

  select s.id, s.organization_id, s.status
    into v_session
  from public.channel_sessions s
  where s.id = v_version.channel_session_id;

  if not found or v_session.organization_id <> p_org_id then
    raise exception 'channel_session_not_found' using errcode = 'P0001';
  end if;
  if v_session.status <> 'WORKING' then
    raise exception 'channel_session_offline' using errcode = 'P0001';
  end if;

  select count(*)
    into v_model_count
  from public.ai_models m
  where m.provider = v_version.provider
    and m.model_id = v_version.model
    and m.deprecated_at is null;

  if v_model_count = 0 then
    raise exception 'model_not_found' using errcode = 'P0001';
  end if;

  v_previous_version_id := v_agent.published_version_id;

  if v_previous_version_id is not null and v_previous_version_id <> p_version_id then
    update public.ai_agent_versions
       set status = 'superseded', superseded_at = v_published_at
     where id = v_previous_version_id;
  end if;

  update public.ai_agent_versions
     set status = 'published',
         published_at = v_published_at,
         superseded_at = null
   where id = p_version_id;

  update public.ai_agents
     set published_version_id = p_version_id,
         updated_at = v_published_at
   where id = p_agent_id;

  return query
    select p_agent_id, p_version_id, v_previous_version_id, v_published_at;
end;
$$;


--
-- Name: fn_publish_followup_flow_version(uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_publish_followup_flow_version(p_org uuid, p_pointer uuid, p_graph jsonb, p_created_by uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pointer record;
  v_version_id uuid;
begin
  select p.id, p.organization_id
    into v_pointer
  from followup_flow_pointers p
  where p.id = p_pointer
  for update;

  if not found or v_pointer.organization_id <> p_org then
    raise exception 'pointer_not_found' using errcode = 'P0001';
  end if;

  insert into followup_flow_versions (organization_id, pointer_id, graph, created_by)
  values (p_org, p_pointer, p_graph, p_created_by)
  returning id into v_version_id;

  update followup_flow_pointers
     set active_version_id = v_version_id,
         status = 'active',
         updated_at = now()
   where id = p_pointer;

  return v_version_id;
end;
$$;


--
-- Name: fn_reaplicar_modulos_instalados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reaplicar_modulos_instalados() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
begin
  for r in select modulo from public.modulos_instalados order by modulo loop
    begin
      if to_regprocedure(format('public.fn_%s_provisionar()', r.modulo)) is null then
        raise exception 'a provisionadora de % n??o existe nesta vers??o', r.modulo;
      end if;
      execute format('select public.%I()', 'fn_' || r.modulo || '_provisionar');
      update public.modulos_instalados
        set estado = 'ativo', motivo_suspensao = null, reaplicado_em = now()
        where modulo = r.modulo;
    exception
      -- Disputa de trava com o app no ar N??O ?? defeito do m??dulo: relan??ar desfaz esta
      -- passada inteira (nenhum m??dulo ?? marcado), e o texto do Postgres ??? "deadlock
      -- detected", "could not obtain lock" ??? ?? o que o kit reconhece como disputa e o faz
      -- aplicar de novo. Suspender aqui tiraria do ar um m??dulo que s?? precisava esperar.
      when deadlock_detected or serialization_failure or lock_not_available then
        raise;
      when others then
        update public.modulos_instalados
          set estado = 'suspenso', motivo_suspensao = sqlerrm
          where modulo = r.modulo;
    end;
  end loop;
  perform pg_notify('pgrst', 'reload schema');
end $$;


--
-- Name: fn_recalcular_cliente_do_contato(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_recalcular_cliente_do_contato(p_org uuid, p_contact uuid, p_emitir boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  c_etiqueta constant text := 'cliente';
  v_antes timestamptz;
  v_tags text[];
  v_reconhecido timestamptz;
  v_dono text;
  v_depois timestamptz;
  v_tem boolean;
  v_novas text[];
  v_resultado text;
begin
  -- TRAVA O CONTATO ANTES DE LER A AGENDA. Na ordem inversa, duas marca????es
  -- simult??neas do mesmo contato gravam um min() velho por cima do certo: em
  -- READ COMMITTED o min() lido DEPOIS da trava enxerga a marca????o concorrente
  -- que j?? commitou.
  --
  -- `for no key update`, e n??o `for update`: ?? a trava que o UPDATE abaixo toma
  -- de qualquer jeito, e ela n??o conflita com o `for key share` que a FK de toda
  -- tabela que aponta para `contacts` toma num INSERT. Medido com `for update`:
  -- a liga????o da regra (trava da organiza????o, depois o contato) e um INSERT de
  -- agendamento (a FK trava o contato, depois o trigger espera a trava da
  -- organiza????o) fechavam `deadlock detected`.
  --
  -- Anonimizado e mesclado n??o recebem escrita derivada nova: sem esta guarda
  -- um agendamento posterior faria "Cliente Anonimizado #N" reaparecer
  -- etiquetado.
  select c.first_service_at, coalesce(c.tags, '{}'::text[]), c.client_recognized_at, c.client_tag_by_system
    into v_antes, v_tags, v_reconhecido, v_dono
    from public.contacts c
   where c.organization_id = p_org
     and c.id = p_contact
     and c.is_anonymized = false
     and c.is_merged_into is null
   for no key update;
  if not found then
    return 'ignorado';
  end if;

  select min(least(a.created_at, a.starts_at)) into v_depois
    from public.calendar_appointments a
   where a.organization_id = p_org
     and a.contact_id = p_contact
     and public.fn_situacao_conta_como_atendimento(a.status);

  -- O caso comum ??? cliente antigo marcando a en??sima hora ??? n??o escreve nada:
  -- `updated_at` n??o se move e o contato n??o vira ru??do de realtime.
  if v_antes is not distinct from v_depois then
    return 'igual';
  end if;

  v_tem := c_etiqueta = any(v_tags);

  -- REDE, e n??o mais a regra: quem l?? o que a equipe fez ?? a guarda da se????o
  -- 4b, na hora da escrita. Isto aqui alcan??a os dois casos que ela n??o v?? ???
  -- um banco que aplicou uma vers??o anterior desta migration (a etiqueta mudou
  -- de m??o antes de a guarda existir) e uma restaura????o com
  -- `session_replication_role = replica`, que desliga trigger.
  if (v_dono = 'added' and not v_tem) or (v_dono = 'removed' and v_tem) then
    v_dono := null;
  end if;

  -- `array_append`/`array_remove` e n??o `||`: sem cast, o `||` l?? o literal
  -- como ARRAY e morre em `malformed array literal` (medido pelo autor no CI).
  v_novas := v_tags;
  if v_antes is null then
    -- Virou cliente. A etiqueta entra se nunca foi reconhecido (a primeira vez)
    -- ou se foi o sistema que a tirou. Se a equipe a tirou, fica fora.
    if not v_tem and (v_reconhecido is null or v_dono = 'removed') then
      v_novas := array_append(v_tags, c_etiqueta);
      v_dono := 'added';
      v_resultado := 'etiquetado';
    else
      v_resultado := 'virou_cliente';
    end if;
  elsif v_depois is null then
    -- Deixou de ser cliente. S?? sai a etiqueta que ?? do sistema.
    if v_tem and v_dono = 'added' then
      v_novas := array_remove(v_tags, c_etiqueta);
      v_dono := 'removed';
      v_resultado := 'desetiquetado';
    else
      v_resultado := 'deixou_de_ser_cliente';
    end if;
  else
    v_resultado := 'mudou_a_data';
  end if;

  -- A ESCRITA SE ANUNCIA. `auth.uid()` continua preenchido aqui dentro ??? uma
  -- `security definer` troca o dono da fun????o, nunca o JWT da sess??o ???, ent??o
  -- sem um sinal expl??cito a guarda da se????o 4b barraria o pr??prio sistema. A
  -- chave ?? de TRANSA????O (`set_config(..., true)`) e volta a 'off' na linha
  -- seguinte: a janela ?? o UPDATE, n??o o resto da transa????o.
  perform set_config('deskcomm.cliente_pela_agenda', 'on', true);

  update public.contacts
     set first_service_at = v_depois,
         client_recognized_at = coalesce(v_reconhecido, case when v_depois is not null then now() end),
         client_tag_by_system = v_dono,
         tags = v_novas,
         updated_at = now()
   where organization_id = p_org
     and id = p_contact;

  perform set_config('deskcomm.cliente_pela_agenda', 'off', true);

  -- UMA VEZ POR CONTATO: s?? quando a etiqueta entra na primeira vez que a regra
  -- o reconhece.
  if v_resultado = 'etiquetado' and v_reconhecido is null and p_emitir then
    -- O MESMO formato que o app emite (app/api/v1/contacts/_handler.ts e
    -- lib/automation/actions/add-tag.ts): `added_tags` + `tags`.
    --
    -- SEM `service_origin`: `emit_event` o carimba sozinho para
    -- contact.tag_added, e o recusaria (42501) vindo de sess??o autenticada.
    -- SEM `caused_by_rule`: a automa????o TEM de ver este evento.
    -- Trigger nunca faz HTTP: a linha vai para event_log e o worker consome.
    perform public.emit_event(
      'contact.tag_added',
      'contact',
      p_contact,
      jsonb_build_object('added_tags', jsonb_build_array(c_etiqueta), 'tags', to_jsonb(v_novas)),
      jsonb_build_object('actor_type', 'system', 'actor_id', 'trg_agendamento_marca_cliente'),
      p_org
    );
  end if;

  return v_resultado;
end $$;


