-- Name: fn_tags_de_conversa_em_uso(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_tags_de_conversa_em_uso(p_org uuid) RETURNS TABLE(tag text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select distinct t
  from public.conversations c, unnest(c.tags) as t
  where c.organization_id = p_org
    and c.tags is not null
  order by t
  limit 200;
$$;


--
-- Name: fn_tags_normalizar(text[], text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_tags_normalizar(p_tags text[], p_de text, p_para text, p_remover boolean) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  -- `distinct on` pela chave can??nica DO RESULTADO, e n??o da entrada.
  --
  -- ?????? Deduplicar pela entrada parece a mesma coisa e n??o ??: no `juntar`, os dois
  -- nomes t??m chaves DIFERENTES por defini????o (?? o que os torna duas etiquetas),
  -- e depois da substitui????o viram o MESMO nome. Medido num Postgres real:
  -- `{VIP, obra}` juntando `obra` em `VIP` devolvia `{VIP, VIP}` ??? a etiqueta
  -- duplicada no array, e `fn_vocabulario_de_tags` conta OCORR??NCIAS, ent??o o
  -- registro passava a pesar 2 na pr??pria tela que deveria arrum??-lo. O caso
  -- `{vip, VIP}` do teste passava por acidente: ali as duas chaves j?? eram
  -- iguais ANTES da substitui????o.
  select coalesce(array_agg(n.tag order by n.ord), '{}'::text[])
  from (
    select distinct on (lower(s.tag)) s.tag, s.ord
    from (
      select case
               when p_remover then null
               when lower(btrim(e.valor)) = lower(btrim(coalesce(p_de, ''))) then btrim(p_para)
               else btrim(e.valor)
             end as tag,
             e.ord
      from unnest(coalesce(p_tags, '{}'::text[])) with ordinality as e(valor, ord)
      where btrim(coalesce(e.valor, '')) <> ''
    ) s
    where s.tag is not null and s.tag <> ''
    order by lower(s.tag), s.ord
  ) as n;
$$;


--
-- Name: fn_telefone_variantes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_telefone_variantes(p_telefone text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with d as (select regexp_replace(coalesce(p_telefone, ''), '\D', '', 'g') as v)
  select case
    when d.v = '' then array[]::text[]
    when d.v not like '55%' then array[d.v]
    when length(d.v) = 13
         and substring(d.v from 5 for 1) = '9'
         and substring(d.v from 6 for 1) between '6' and '9'
      then array[d.v, substring(d.v from 1 for 4) || substring(d.v from 6)]
    when length(d.v) = 12
         and substring(d.v from 5 for 1) between '6' and '9'
      then array[d.v, substring(d.v from 1 for 4) || '9' || substring(d.v from 5)]
    else array[d.v]
  end
  from d;
$$;


