--
-- Name: calendar_google_reconcilable_appointments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.calendar_google_reconcilable_appointments WITH (security_invoker='true') AS
 SELECT id,
    organization_id,
    event_type_id,
    title,
    description,
    starts_at,
    ends_at,
    time_zone,
    status,
    owner_user_id,
    contact_id,
    conversation_id,
    location_kind,
    location_details,
    meeting_url,
    notes,
    cancellation_reason,
    cancelled_at,
    rescheduled_from_id,
    created_by_kind,
    created_by_user_id,
    created_by_agent_id,
    source,
    reminder_sent_at,
    google_connection_id,
    google_calendar_id,
    google_event_id,
    google_ical_uid,
    google_sequence,
    google_synced_at,
    google_sync_error,
    created_at,
    updated_at,
    revision,
    revision_started_at,
    outcome_source_kind,
    outcome_user_id,
    outcome_message_id,
    outcome_recorded_at,
    confirmation_next_at,
    google_local_revision,
    google_synced_local_revision,
    google_etag,
    google_base_projection,
    google_conflict,
    google_pending_write,
    google_claim_token,
    google_claim_epoch,
    google_claim_until,
    google_next_attempt_at,
    meeting_state,
    meeting_request_id,
    meeting_requested_at,
    meeting_received_at,
    meeting_ready_at,
    meeting_attempts,
    meeting_last_error,
    meeting_next_attempt_at,
    meeting_delivery,
    meeting_delivery_job_id,
    guest_email,
    reminder_sent_offsets_minutes,
    needs_google_push
   FROM public.calendar_appointments a
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.contacts c
          WHERE ((c.organization_id = a.organization_id) AND (c.id = a.contact_id) AND c.is_anonymized))));


