    CONSTRAINT channel_sessions_provider_ref_check CHECK ((((provider = 'waha'::text) AND (waha_session_name IS NOT NULL)) OR ((provider = 'meta_cloud'::text) AND (meta_phone_number_id IS NOT NULL)) OR ((provider = ANY (ARRAY['zernio'::text, 'zernio_social'::text])) AND (zernio_account_id IS NOT NULL)) OR ((provider = 'wacalls'::text) AND (wacalls_session_id IS NOT NULL)))),
    CONSTRAINT channel_sessions_status_check CHECK ((status = ANY (ARRAY['STARTING'::text, 'SCAN_QR_CODE'::text, 'WORKING'::text, 'STOPPED'::text, 'FAILED'::text])))
);


