    CONSTRAINT crm_lead_scores_needs_reason CHECK (((ai_probability IS NULL) OR ((ai_probability_reason IS NOT NULL) AND (btrim(ai_probability_reason) <> ''::text) AND (COALESCE(jsonb_array_length((ai_probability_evidence -> 'factors'::text)), 0) > 0) AND (ai_probability_evidence @? '$."factors"[*]."ancora"'::jsonpath)))),
    CONSTRAINT crm_lead_scores_range CHECK (((ai_probability IS NULL) OR ((ai_probability >= (0)::numeric) AND (ai_probability <= (100)::numeric))))
);


