    CONSTRAINT passagens_de_atendimento_origem_check CHECK ((origem = ANY (ARRAY['pedido_explicito'::text, 'opt_out_provavel'::text, 'ferramenta_do_modelo'::text, 'teto_de_gasto'::text, 'caso_escalado'::text, 'sentimento'::text, 'legado_pedido'::text, 'legado_juridico'::text, 'legado_etapa'::text, 'legado_confianca'::text, 'legado_teto'::text, 'mcp_externo'::text, 'runtime_nativo'::text]))),
    CONSTRAINT passagens_de_atendimento_tentativas_check CHECK ((jsonb_typeof(tentativas) = 'array'::text)),
    CONSTRAINT passagens_reconhecimento_coerente CHECK (((reconhecido_por IS NULL) OR (reconhecido_em IS NOT NULL)))
);


