CREATE TABLE public.voip_trunk_settings (
    organization_id uuid NOT NULL,
    host text NOT NULL,
    port integer DEFAULT 5060 NOT NULL,
    username text NOT NULL,
    password_encrypted bytea NOT NULL,
    password_iv bytea NOT NULL,
    password_tag bytea NOT NULL,
    password_last4 text NOT NULL,
    from_domain text,
    endpoint_name text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: voip_trunk_settings_safe; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.voip_trunk_settings_safe WITH (security_invoker='true') AS
 SELECT organization_id,
    host,
    port,
    username,
    password_last4,
    from_domain,
    endpoint_name,
    is_active,
    updated_by,
    created_at,
    updated_at
   FROM public.voip_trunk_settings;


