--
-- Name: webhook_events_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_events_log (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    organization_id uuid,
    channel_session_id uuid,
    provider text DEFAULT 'waha'::text NOT NULL,
    webhook_path_token text,
    http_method text DEFAULT 'POST'::text NOT NULL,
    headers jsonb,
    raw_body text,
    payload_parsed jsonb,
    signature_header text,
    valid_signature boolean,
    event_type text,
    external_id text,
    status text DEFAULT 'received'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    error_message text,
    processed_at timestamp with time zone,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    archived_at timestamp with time zone,
    CONSTRAINT webhook_events_log_provider_check CHECK ((provider = ANY (ARRAY['waha'::text, 'nuvemshop'::text, 'generic'::text, 'meta_cloud'::text, 'zernio'::text]))),
    CONSTRAINT webhook_events_log_status_check CHECK ((status = ANY (ARRAY['received'::text, 'processed'::text, 'error'::text, 'dead'::text])))
);


--
-- Name: COLUMN webhook_events_log.raw_body; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_events_log.raw_body IS 'Corpo cru como o provedor mandou. NULL = existiu e foi descartado pela reten????o; `archived_at` diz quando.';


--
-- Name: COLUMN webhook_events_log.archived_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_events_log.archived_at IS 'Quando as colunas pesadas (raw_body, payload_parsed, headers) foram descartadas pela reten????o. NULL = a linha ainda tem o corpo.';


