-- Name: organization_extensions tenant_isolation_organization_extensions_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY tenant_isolation_organization_extensions_select ON public.organization_extensions FOR SELECT TO authenticated USING (((organization_id IN ( SELECT public.fn_user_org_ids() AS fn_user_org_ids)) AND ((EXISTS ( SELECT 1
   FROM public.user_organizations u
  WHERE ((u.organization_id = organization_extensions.organization_id) AND (u.user_id = auth.uid()) AND (u.accepted_at IS NOT NULL) AND (u.revoked_at IS NULL)))) OR (EXISTS ( SELECT 1
   FROM ( SELECT public.fn_support_context() AS s) c
  WHERE (((c.s ->> 'status'::text) = 'active'::text) AND (((c.s ->> 'organization_id'::text))::uuid = organization_extensions.organization_id)))))));


